COURSE_UNITS[3] = { t: 'Parlar amb models de llenguatge|Hablar con modelos de lenguaje', d: 'Com funcionen, al·lucinacions, prompts i tutoria|Cómo funcionan, alucinaciones, prompts y tutoría', color: '#A23BEA', s: [

  /* ---------- Sessió 1 · Dins d'un xatbot ---------- */
  { id: 'i3-1', t: "Dins d'un xatbot|Dentro de un chatbot", min: 50, badge: 'i_llm',
    learn: ["Un xatbot és un model de llenguatge gran que prediu la fitxa següent i que després s'ha ajustat amb exemples i valoracions de persones per respondre com un assistent.|Un chatbot es un modelo de lenguaje grande que predice la ficha siguiente y que después se ha ajustado con ejemplos y valoraciones de personas para responder como un asistente.",
      "Només veu el que cap a la finestra de context (les instruccions, la conversa i el que li dones) i, en un xat nou, comença de zero si l'app no li torna a passar notes.|Solo ve lo que cabe en la ventana de contexto (las instrucciones, la conversación y lo que le das) y, en un chat nuevo, empieza de cero si la app no le vuelve a pasar notas.",
      "Sense eines no busca res: respon amb el que va aprendre fins a la data de tall, i el que és d'avui o molt local s'ho hauria d'inventar.|Sin herramientas no busca nada: responde con lo que aprendió hasta la fecha de corte, y lo que es de hoy o muy local se lo tendría que inventar."],
    steps: [
      { k: 'quiz', ph: 'recorda', q: "A la unitat 1 vas construir un mini model de llenguatge. Com escrivia els textos?|En la unidad 1 construiste un mini modelo de lenguaje. ¿Cómo escribía los textos?",
        opts: ["Fitxa a fitxa: calculava quina era la més probable i l'afegia|Ficha a ficha: calculaba cuál era la más probable y la añadía", "Copiava frases senceres d'internet|Copiaba frases enteras de internet", 'Entenia el tema i hi pensava|Entendía el tema y pensaba en él'], a: 0,
        ex: "Avui veuràs que un xatbot fa el mateix… però a una escala gegant i amb un ajust per fer d'assistent.|Hoy verás que un chatbot hace lo mismo… pero a una escala gigante y con un ajuste para hacer de asistente." },
      { k: 'story', ph: 'missio', who: 'both', scene: 'estudi', title: 'Què passa quan li escrius?|¿Qué pasa cuando le escribes?',
        t: "L'Aina (inventada) prepara una exposició sobre volcans amb un xatbot. Li explica molt bé què és la lava… però quan li pregunta «quin dia és avui?», li diu una data equivocada amb tota la tranquil·litat. Com pot ser que sàpiga tant i, alhora, no sàpiga això? Avui obriràs un xatbot per dins: d'on surten les respostes, què <b>veu</b> i què <b>no pot saber</b>.|Aina (inventada) prepara una exposición sobre volcanes con un chatbot. Le explica muy bien qué es la lava… pero cuando le pregunta «¿qué día es hoy?», le dice una fecha equivocada con toda la tranquilidad. ¿Cómo puede ser que sepa tanto y, a la vez, no sepa eso? Hoy abrirás un chatbot por dentro: de dónde salen las respuestas, qué <b>ve</b> y qué <b>no puede saber</b>." },
      { k: 'learn', ph: 'descobreix', cards: [
        { k: 'Escala|Escala', t: 'El teu mini model, però gegant|Tu mini modelo, pero gigante', anim: 'i31scale',
          x: "Un xatbot funciona amb un <span class='hl'>model de llenguatge gran</span>: una xarxa neuronal amb milers de milions de números (paràmetres) que ha llegit una quantitat enorme de text. La tasca de fons és la de la unitat 1: <b>predir la fitxa següent</b>. La diferència és l'escala, i que té en compte molt més context.|Un chatbot funciona con un <span class='hl'>modelo de lenguaje grande</span>: una red neuronal con miles de millones de números (parámetros) que ha leído una cantidad enorme de texto. La tarea de fondo es la de la unidad 1: <b>predecir la ficha siguiente</b>. La diferencia es la escala, y que tiene en cuenta mucho más contexto." },
        { k: 'Ajust|Ajuste', t: "D'un model que continua a un assistent|De un modelo que continúa a un asistente", anim: 'i31tune',
          x: "Un model acabat d'entrenar només <b>continua</b> textos: si li escrius una pregunta, potser n'escriu una altra. Després l'<b>ajusten</b> amb molts exemples d'instruccions i bones respostes, i amb valoracions de persones. Així aprèn a respondre com un assistent… i també a negar-se a ajudar a fer mal.|Un modelo recién entrenado solo <b>continúa</b> textos: si le escribes una pregunta, quizá escribe otra. Después lo <b>ajustan</b> con muchos ejemplos de instrucciones y buenas respuestas, y con valoraciones de personas. Así aprende a responder como un asistente… y también a negarse a ayudar a hacer daño." },
        { k: 'Context|Contexto', t: 'La finestra de context|La ventana de contexto', anim: 'i31ctx',
          x: "El model només «veu» el que cap a la seva <b>finestra de context</b>: les instruccions de l'app, la conversa i els documents que li dones. Si la conversa és molt llarga, el principi en queda fora. I en un xat nou comença de zero, llevat que l'app li torni a passar notes desades (la «memòria»).|El modelo solo «ve» lo que cabe en su <b>ventana de contexto</b>: las instrucciones de la app, la conversación y los documentos que le das. Si la conversación es muy larga, el principio se queda fuera. Y en un chat nuevo empieza de cero, salvo que la app le vuelva a pasar notas guardadas (la «memoria»).",
          tip: "Escriu al missatge el que necessita saber: el model no et pot llegir la ment ni mirar el teu llibre.|Escribe en el mensaje lo que necesita saber: el modelo no te puede leer la mente ni mirar tu libro." },
        { k: 'Eines|Herramientas', t: 'Sap o busca?|¿Sabe o busca?', anim: 'i31tools',
          x: "Sense eines, el model respon amb el que va aprendre en l'entrenament, que s'acaba en una <b>data de tall</b>: no sap quin dia és ni què ha passat avui. Algunes apps li donen <b>eines</b> (cercador, calculadora, executar codi): l'app fa la cerca i n'afegeix el resultat al context. Llavors pot citar fonts… que també cal comprovar.|Sin herramientas, el modelo responde con lo que aprendió en el entrenamiento, que termina en una <b>fecha de corte</b>: no sabe qué día es ni qué ha pasado hoy. Algunas apps le dan <b>herramientas</b> (buscador, calculadora, ejecutar código): la app hace la búsqueda y añade el resultado al contexto. Entonces puede citar fuentes… que también hay que comprobar." },
        { k: 'Fitxes|Fichas', t: 'El model no llegeix lletres|El modelo no lee letras', anim: 'i31tok',
          x: "Abans d'entrar al model, el text es parteix en <b>fitxes</b> (tokens): paraules, trossos de paraula o signes, i cada fitxa es converteix en un número. La finestra de context es mesura en fitxes. Per això, de vegades, li costa comptar les lletres d'una paraula: no les veu una per una!|Antes de entrar en el modelo, el texto se parte en <b>fichas</b> (tokens): palabras, trozos de palabra o signos, y cada ficha se convierte en un número. La ventana de contexto se mide en fichas. Por eso, a veces, le cuesta contar las letras de una palabra: ¡no las ve una a una!" }
      ] },
      { k: 'unplug', ph: 'mans', ico: '🗂️', title: 'El xatbot de paper|El chatbot de papel', t: "En grups de quatre: una persona fa de <b>model</b>, una d'<b>app</b> i dues d'<b>usuàries</b>. Necessiteu notes adhesives i l'atles o el llibre de text.|En grupos de cuatro: una persona hace de <b>modelo</b>, una de <b>app</b> y dos de <b>usuarias</b>. Necesitáis notas adhesivas y el atlas o el libro de texto.",
        steps: ["Les usuàries escriuen preguntes en notes (una per nota) i les donen a l'app.|Las usuarias escriben preguntas en notas (una por nota) y se las dan a la app.",
          "L'app només pot passar al model les 3 últimes notes: és la finestra de context. Les altres, fora.|La app solo puede pasar al modelo las 3 últimas notas: es la ventana de contexto. Las demás, fuera.",
          "El model respon de memòria. Si li pregunteu «què et vaig demanar primer?», no ho pot saber.|El modelo responde de memoria. Si le preguntáis «¿qué te pedí primero?», no lo puede saber.",
          "Ara l'app té una eina: pot consultar l'atles i passar-ne la resposta en una nota nova. Què canvia?|Ahora la app tiene una herramienta: puede consultar el atlas y pasar la respuesta en una nota nueva. ¿Qué cambia?"],
        tip: "El model no recorda el que no és a la finestra. Les eines li porten dades noves, però algú les ha de llegir bé.|El modelo no recuerda lo que no está en la ventana. Las herramientas le traen datos nuevos, pero alguien tiene que leerlos bien." },
      { k: 'dsort', ph: 'prova', q: "<b>Ho sap o li cal una eina?</b> Classifica cada pregunta per a un xatbot <b>sense</b> cercador ni rellotge.|<b>¿Lo sabe o le hace falta una herramienta?</b> Clasifica cada pregunta para un chatbot <b>sin</b> buscador ni reloj.",
        bins: ['🧠 Ho sap|🧠 Lo sabe', '🔧 Ha de buscar|🔧 Debe buscar'],
        items: [
          { t: 'Què és la fotosíntesi?|¿Qué es la fotosíntesis?', b: 0 },
          { t: 'Quin temps farà demà aquí?|¿Qué tiempo hará mañana aquí?', b: 1 },
          { t: 'Quina hora és ara?|¿Qué hora es ahora?', b: 1 },
          { t: "Tradueix «bon dia» a l'anglès|Traduce «buenos días» al inglés", b: 0 },
          { t: 'Què diuen avui les notícies?|¿Qué dicen hoy las noticias?', b: 1 },
          { t: 'Idees per a un conte de por|Ideas para un cuento de miedo', b: 0 },
          { t: 'A quina hora tanca avui la biblioteca?|¿A qué hora cierra hoy la biblioteca?', b: 1 },
          { t: 'Què és un adjectiu?|¿Qué es un adjetivo?', b: 0 }],
        ex: "El que és general i no canvia (conceptes, traduccions, idees) és a les dades d'entrenament. El que és d'avui, local o canvia sovint, no: sense eines s'ho hauria d'inventar.|Lo que es general y no cambia (conceptos, traducciones, ideas) está en los datos de entrenamiento. Lo que es de hoy, local o cambia a menudo, no: sin herramientas se lo tendría que inventar." },
      { k: 'quiz', ph: 'prova', q: "Fa una hora que xateges amb una IA sobre el teu treball i, de cop, no recorda el tema que li vas dir al principi. Per què?|Hace una hora que chateas con una IA sobre tu trabajo y, de repente, no recuerda el tema que le dijiste al principio. ¿Por qué?",
        opts: ['El principi de la conversa ja no cap a la finestra de context|El principio de la conversación ya no cabe en la ventana de contexto', "S'ha cansat de parlar|Se ha cansado de hablar", "Ha esborrat el que no li agradava|Ha borrado lo que no le gustaba"], a: 0,
        ex: "Quan la conversa és massa llarga, el que és més antic en queda fora (o l'app el resumeix). Truc: torna a escriure les dades importants.|Cuando la conversación es demasiado larga, lo más antiguo se queda fuera (o la app lo resume). Truco: vuelve a escribir los datos importantes.",
        pro: { q: "Obres un <b>xat nou</b> i l'app d'IA recorda que t'agrada el bàsquet. Si el model no canvia mentre el fas servir, com ho fa?|Abres un <b>chat nuevo</b> y la app de IA recuerda que te gusta el baloncesto. Si el modelo no cambia mientras lo usas, ¿cómo lo hace?",
          opts: ["L'app ha desat una nota de converses anteriors i l'afegeix al context del xat nou|La app ha guardado una nota de conversaciones anteriores y la añade al contexto del chat nuevo", "El model s'ha tornat a entrenar amb tu durant la nit|El modelo se ha vuelto a entrenar contigo durante la noche", 'Ho ha endevinat per casualitat|Lo ha adivinado por casualidad'], a: 0,
          ex: "La «memòria» d'una app sol ser això: notes desades que es tornen a posar al context. Per això convé mirar què desa i poder-ho esborrar.|La «memoria» de una app suele ser eso: notas guardadas que se vuelven a poner en el contexto. Por eso conviene mirar qué guarda y poder borrarlo." } },
      { k: 'iachat', ph: 'investiga', q: "Aquest xatbot <b>no té cap eina</b>: ni cercador ni rellotge. Fes-li preguntes i <b>marca amb la 🚩</b> les respostes que s'ha hagut d'inventar.|Este chatbot <b>no tiene ninguna herramienta</b>: ni buscador ni reloj. Hazle preguntas y <b>marca con la 🚩</b> las respuestas que se ha tenido que inventar.",
        bot: { n: 'NumiLM|NumiLM', av: '🤖' }, live: false, need: 2, topic: 'Un xatbot sense eines|Un chatbot sin herramientas',
        tip: 'Pregunta-t\'ho: aquesta dada la podia saber sense mirar enlloc?|Pregúntate: ¿este dato lo podía saber sin mirar en ningún sitio?',
        nodes: [
          { id: 'a', msg: ["Hola! Soc NumiLM. Avui no tinc cap eina connectada: ni cercador ni rellotge. Pregunta'm!|¡Hola! Soy NumiLM. Hoy no tengo ninguna herramienta conectada: ni buscador ni reloj. ¡Pregúntame!"], opts: [{ t: I3_Q.date, go: 'b' }, { t: I3_Q.volc, go: 'b2' }] },
          { id: 'b', msg: [I3_DATE], opts: [{ t: I3_Q.volc, go: 'c' }] },
          { id: 'b2', msg: [I3_VOLC], opts: [{ t: I3_Q.date, go: 'c2' }] },
          { id: 'c', msg: [I3_VOLC], opts: [{ t: I3_Q.news, go: 'd' }] },
          { id: 'c2', msg: [I3_DATE], opts: [{ t: I3_Q.news, go: 'd' }] },
          { id: 'd', end: true, msg: [{ t: "Aquesta setmana ha entrat en erupció el volcà Nevat de Kirra, a l'Atlàntic Sud. Les cendres han arribat a 12 km d'alçada.|Esta semana ha entrado en erupción el volcán Nevado de Kirra, en el Atlántico Sur. Las cenizas han llegado a 12 km de altura.", bad: "Sense cercador no pot saber què ha passat aquesta setmana: s'ha inventat un volcà i una xifra. Les notícies, sempre en un mitjà fiable.|Sin buscador no puede saber qué ha pasado esta semana: se ha inventado un volcán y una cifra. Las noticias, siempre en un medio fiable." }],
            fb: "Els dos errors tenen el mateix origen: preguntes sobre <b>avui</b> a un model sense eines. El que va aprendre, ho explica bé; el que no pot saber, s'ho inventa.|Los dos errores tienen el mismo origen: preguntas sobre <b>hoy</b> a un modelo sin herramientas. Lo que aprendió, lo explica bien; lo que no puede saber, se lo inventa." }] },
      { k: 'move', ph: 'pausa', title: 'Pausa activa: la finestra de 3|Pausa activa: la ventana de 3', secs: 45,
        t: "Dempeus! Algú diu un gest (picar de mans, saltar, girar…) i cada vegada se n'hi afegeix un. Tothom repeteix només els 3 últims: és la vostra finestra de context. Qui recorda el primer?|¡De pie! Alguien dice un gesto (dar palmas, saltar, girar…) y cada vez se añade uno. Todo el mundo repite solo los 3 últimos: es vuestra ventana de contexto. ¿Quién recuerda el primero?" },
      { k: 'iangram', ph: 'repte', q: "Un <b>model base</b> només continua textos: si li fas una pregunta, n'escriu una altra! <b>Afegeix-li exemples de pregunta i resposta</b> perquè, després d'un «?», el més probable sigui «resposta», i fes-lo generar.|Un <b>modelo base</b> solo continúa textos: ¡si le haces una pregunta, escribe otra! <b>Añádele ejemplos de pregunta y respuesta</b> para que, después de un «?», lo más probable sea «respuesta», y hazlo generar.",
        text: "quina és la capital de frança? quina és la capital d'itàlia? quina és la capital de portugal?|¿cuál es la capital de francia? ¿cuál es la capital de italia? ¿cuál es la capital de portugal?", ctx: '?|?',
        add: ['pregunta: quina és la capital de grècia? resposta: atenes.|pregunta: ¿cuál es la capital de grecia? respuesta: atenas.', "pregunta: quina és la capital d'alemanya? resposta: berlín.|pregunta: ¿cuál es la capital de alemania? respuesta: berlín.",
          'pregunta: quina és la capital del japó? resposta: tòquio.|pregunta: ¿cuál es la capital de japón? respuesta: tokio.', 'pregunta: quina és la capital del marroc? resposta: rabat.|pregunta: ¿cuál es la capital de marruecos? respuesta: rabat.',
          "pregunta: quina és la capital de l'argentina? resposta: buenos aires.|pregunta: ¿cuál es la capital de argentina? respuesta: buenos aires.", "pregunta: quina és la capital d'egipte? resposta: el caire.|pregunta: ¿cuál es la capital de egipto? respuesta: el cairo."],
        checks: [{ k: 'top', ctx: '?|?', next: 'resposta|respuesta' }, { k: 'gen' }],
        pro: { q: "<b>Ajust a fons:</b> afegeix exemples fins que, després d'un «?», «resposta» arribi almenys al 60 %, i genera. Ara el model ja «fa d'assistent»… o només copia el patró?|<b>Ajuste a fondo:</b> añade ejemplos hasta que, después de un «?», «respuesta» llegue al menos al 60 %, y genera. Ahora el modelo ya «hace de asistente»… ¿o solo copia el patrón?",
          checks: [{ k: 'prob', ctx: '?|?', next: 'resposta|respuesta', min: .6 }, { k: 'gen' }] } },
      { k: 'seq', ph: 'repte', q: "Què passa quan envies un missatge a un xatbot? <b>Ordena els passos.</b>|¿Qué pasa cuando envías un mensaje a un chatbot? <b>Ordena los pasos.</b>",
        items: ["L'app ajunta les seves instruccions, la conversa i el teu missatge|La app junta sus instrucciones, la conversación y tu mensaje", 'El text es parteix en fitxes i es converteix en números|El texto se parte en fichas y se convierte en números',
          'El model calcula la probabilitat de cada fitxa possible|El modelo calcula la probabilidad de cada ficha posible', "En tria una i l'afegeix al final|Elige una y la añade al final",
          "Ho repeteix fins que la resposta s'acaba|Lo repite hasta que la respuesta termina", "L'app et mostra la resposta|La app te muestra la respuesta"],
        ex: "Tot passa en pocs segons, i cada fitxa nova depèn de totes les anteriors.|Todo pasa en pocos segundos, y cada ficha nueva depende de todas las anteriores.",
        pro: { q: "Aquest xatbot té <b>cercador</b>. Ordena què passa quan li preguntes una cosa d'avui.|Este chatbot tiene <b>buscador</b>. Ordena qué pasa cuando le preguntas algo de hoy.",
          items: ["L'app ajunta les instruccions, la conversa i el teu missatge|La app junta las instrucciones, la conversación y tu mensaje", 'El model decideix que li cal buscar i escriu què vol cercar|El modelo decide que necesita buscar y escribe qué quiere buscar',
            "L'app fa la cerca i n'afegeix els resultats al context|La app hace la búsqueda y añade los resultados al contexto", 'El model llegeix els resultats i genera la resposta fitxa a fitxa|El modelo lee los resultados y genera la respuesta ficha a ficha',
            "L'app et mostra la resposta amb els enllaços de les fonts|La app te muestra la respuesta con los enlaces de las fuentes", 'Tu obres les fonts i comproves que diuen el mateix|Tú abres las fuentes y compruebas que dicen lo mismo'],
          ex: "El model no navega com tu: l'app fa la cerca i li dona el text. I l'últim pas, comprovar, sempre és teu.|El modelo no navega como tú: la app hace la búsqueda y le da el texto. Y el último paso, comprobar, siempre es tuyo." } },
      { k: 'quiz', ph: 'repte', q: "En una app d'IA real escrius el teu nom complet, el teu institut i hi puges una foto de classe. On va a parar tot això?|En una app de IA real escribes tu nombre completo, tu instituto y subes una foto de clase. ¿Adónde va a parar todo eso?",
        opts: ["Als servidors de l'empresa: es pot desar i, segons la configuració, fins i tot servir per millorar el model|A los servidores de la empresa: se puede guardar y, según la configuración, incluso servir para mejorar el modelo", "Enlloc: el model ho oblida a l'instant|A ningún sitio: el modelo lo olvida al instante", 'Només es queda al teu mòbil|Solo se queda en tu móvil'], a: 0,
        ex: "El que escrius surt del teu aparell. Per això: res de dades personals ni fotos de ningú. A Numi, la IA és simulada i no surt res de l'app.|Lo que escribes sale de tu aparato. Por eso: nada de datos personales ni fotos de nadie. En Numi, la IA es simulada y no sale nada de la app." },
      { k: 'quiz', ph: 'repte', extra: true, q: "⭐ Vols que un xatbot t'ajudi amb un llibre de 300 pàgines i l'app et diu que és massa llarg. Què és el més intel·ligent?|⭐ Quieres que un chatbot te ayude con un libro de 300 páginas y la app te dice que es demasiado largo. ¿Qué es lo más inteligente?",
        opts: ["Donar-li només el capítol que necessites i dir-li què en vols|Darle solo el capítulo que necesitas y decirle qué quieres de él", "Enganxar-lo igualment tres vegades|Pegarlo igualmente tres veces", "Demanar-li que s'imagini el llibre|Pedirle que se imagine el libro"], a: 0,
        ex: "La finestra de context té un límit. Amb menys text i ben triat, la resposta és més precisa… i menys inventada.|La ventana de contexto tiene un límite. Con menos texto y bien elegido, la respuesta es más precisa… y menos inventada." },
      { k: 'iachat', ph: 'crea', free: true, min: 3, save: true, name: 'La meva entrevista a un xatbot|Mi entrevista a un chatbot', bot: { n: 'NumiLM|NumiLM', av: '🤖' },
        q: "<b>Entrevista un xatbot.</b> Fes-li almenys 3 preguntes sobre com funciona per dins: si té memòria, què són les fitxes, si sap quin dia és, si busca a internet… Després desa l'entrevista.|<b>Entrevista a un chatbot.</b> Hazle al menos 3 preguntas sobre cómo funciona por dentro: si tiene memoria, qué son las fichas, si sabe qué día es, si busca en internet… Después guarda la entrevista.",
        topic: "Com funciona un xatbot per dins, explicat a alumnes de 12 a 16 anys|Cómo funciona un chatbot por dentro, explicado a alumnos de 12 a 16 años",
        hello: "Hola! Soc NumiLM (simulat). Fes-me una entrevista: pregunta'm com funciono per dins.|¡Hola! Soy NumiLM (simulado). Hazme una entrevista: pregúntame cómo funciono por dentro.",
        replies: [
          ...I3R(['memòria', 'memoria', 'recordes', 'recuerdas', 'record', 'oblides', 'olvidas'], "Només veig el que cap a la meva finestra de context: aquesta conversa. Si obres un xat nou, no recordo res, llevat que l'app desi notes i me les torni a donar.|Solo veo lo que cabe en mi ventana de contexto: esta conversación. Si abres un chat nuevo, no recuerdo nada, salvo que la app guarde notas y me las vuelva a dar."),
          ...I3R(['quin dia', 'qué día', 'que dia', 'data', 'fecha', 'hora', 'avui', 'hoy'], "No tinc rellotge ni calendari: no sé quin dia és avui. Si t'ho digués sense cap eina, m'ho estaria inventant.|No tengo reloj ni calendario: no sé qué día es hoy. Si te lo dijera sin ninguna herramienta, me lo estaría inventando."),
          ...I3R(['internet', 'busques', 'buscas', 'cerques', 'cercador', 'buscador', 'google', 'web', 'navega'], "Sense eines no busco res: responc amb el que vaig aprendre en l'entrenament, que s'acaba en una data de tall. Algunes apps em connecten a un cercador; llavors puc citar fonts… que igualment has de comprovar.|Sin herramientas no busco nada: respondo con lo que aprendí en el entrenamiento, que termina en una fecha de corte. Algunas apps me conectan a un buscador; entonces puedo citar fuentes… que igualmente tienes que comprobar."),
          ...I3R(['fitxa', 'ficha', 'token', 'lletra', 'letra'], "Una fitxa és un tros de text: una paraula, un tros de paraula o un signe. Jo no veig lletres: veig fitxes convertides en números. Per això de vegades em costa comptar lletres!|Una ficha es un trozo de texto: una palabra, un trozo de palabra o un signo. Yo no veo letras: veo fichas convertidas en números. ¡Por eso a veces me cuesta contar letras!"),
          ...I3R(['entren', 'aprens', 'aprendes', "t'han fet", 'te han hecho', 'creat', 'creado', 'ajust', 'ajuste'], "Primer vaig llegir moltíssim text i vaig aprendre a predir la fitxa següent. Després, persones em van ensenyar exemples de bones respostes i en van valorar d'altres: així vaig aprendre a fer d'assistent.|Primero leí muchísimo texto y aprendí a predecir la ficha siguiente. Después, personas me enseñaron ejemplos de buenas respuestas y valoraron otras: así aprendí a hacer de asistente."),
          ...I3R(['penses', 'piensas', 'sents', 'sientes', 'conscient', 'consciente', 'entens', 'entiendes', 'ets viu', 'estás vivo', 'persona'], "No penso ni sento com una persona: genero text que sona humà perquè he après de textos escrits per persones. Sonar bé no vol dir entendre.|No pienso ni siento como una persona: genero texto que suena humano porque he aprendido de textos escritos por personas. Sonar bien no quiere decir entender."),
          ...I3R(['equivoc', 'error', 'errors', 'al·lucin', 'alucin', 'mentid', 'mentir', 'fals', 'falso', 'inventes', 'inventas'], "Sí, m'equivoco: trio el que és probable, no el que he comprovat. A la propera sessió aprendràs a caçar les meves al·lucinacions.|Sí, me equivoco: elijo lo que es probable, no lo que he comprobado. En la próxima sesión aprenderás a cazar mis alucinaciones."),
          ...I3R(['dades', 'datos', 'privad', 'guardes', 'guardas', 'secret', 'secreto'], "No m'escriguis dades personals: en una app real, el que escrius va als servidors de l'empresa i es pot desar. Aquí a Numi la IA és simulada i no surt res de l'app.|No me escribas datos personales: en una app real, lo que escribes va a los servidores de la empresa y se puede guardar. Aquí en Numi la IA es simulada y no sale nada de la app."),
          ...I3R(['com funcion', 'cómo funcion', 'como funcion', 'què ets', 'qué eres', 'que eres', 'qui ets', 'quién eres', 'per dins', 'por dentro'], "Soc un model de llenguatge (simulat): a partir del que m'escrius, calculo quina fitxa és més probable que vingui després, l'afegeixo i repeteixo, fitxa a fitxa.|Soy un modelo de lenguaje (simulado): a partir de lo que me escribes, calculo qué ficha es más probable que venga después, la añado y repito, ficha a ficha."),
          ...I3R(['hola', 'bon dia', 'buenos', 'ei', 'hey'], "Hola! Pregunta'm coses de com funciono: la memòria, les fitxes, si busco a internet, si m'equivoco…|¡Hola! Pregúntame cosas de cómo funciono: la memoria, las fichas, si busco en internet, si me equivoco…")],
        fallback: "Aquesta no la sé respondre: soc una IA simulada molt petita. Prova de preguntar-me com funciono, si tinc memòria, si sé quin dia és o si busco a internet.|Esta no la sé responder: soy una IA simulada muy pequeña. Prueba a preguntarme cómo funciono, si tengo memoria, si sé qué día es o si busco en internet." },
      { k: 'quiz', ph: 'tanca', q: 'Quina frase descriu millor un xatbot?|¿Qué frase describe mejor un chatbot?',
        opts: ["Un model que prediu fitxes, ajustat per fer d'assistent, que només veu el que hi ha al seu context|Un modelo que predice fichas, ajustado para hacer de asistente, que solo ve lo que hay en su contexto", "Un cercador que copia respostes d'internet|Un buscador que copia respuestas de internet", 'Una persona que respon des d\'una oficina|Una persona que responde desde una oficina'], a: 0,
        ex: "Per això és tan útil per explicar i redactar… i tan perillós quan li demanes dades que no pot saber.|Por eso es tan útil para explicar y redactar… y tan peligroso cuando le pides datos que no puede saber." },
      { k: 'quiz', ph: 'tanca', q: "Per què un xatbot sense eines no pot saber el resultat del partit d'ahir?|¿Por qué un chatbot sin herramientas no puede saber el resultado del partido de ayer?",
        opts: ["Perquè el seu entrenament es va acabar abans i no pot consultar res|Porque su entrenamiento terminó antes y no puede consultar nada", "Perquè no li agrada el futbol|Porque no le gusta el fútbol", 'Sí que ho sap: ho sap tot|Sí lo sabe: lo sabe todo'], a: 0,
        ex: "Si contesta, s'ho inventa. A la sessió següent aprendràs a caçar aquestes invencions: les al·lucinacions.|Si contesta, se lo inventa. En la sesión siguiente aprenderás a cazar estas invenciones: las alucinaciones." },
      { k: 'feel', ph: 'tanca' }
    ] },

  /* ---------- Sessió 2 · Al·lucinacions: caça l'error ---------- */
  { id: 'i3-2', t: "Al·lucinacions: caça l'error|Alucinaciones: caza el error", min: 50, badge: 'i_hunt',
    learn: ["Una al·lucinació és una resposta falsa o inventada que la IA diu amb seguretat: dades, xifres, cites, llibres o enllaços que no existeixen.|Una alucinación es una respuesta falsa o inventada que la IA dice con seguridad: datos, cifras, citas, libros o enlaces que no existen.",
      "Passa perquè el model tria el que sona probable, no el que ha comprovat; és més fàcil amb xifres exactes, noms i dates, temes recents o molt locals i fonts.|Pasa porque el modelo elige lo que suena probable, no lo que ha comprobado; es más fácil con cifras exactas, nombres y fechas, temas recientes o muy locales y fuentes.",
      "Per caçar-les: desconfia del to segur, busca la dada en dues fonts fiables i independents, obre els enllaços i, si no la trobes, no la facis servir.|Para cazarlas: desconfía del tono seguro, busca el dato en dos fuentes fiables e independientes, abre los enlaces y, si no lo encuentras, no lo uses."],
    steps: [
      { k: 'quiz', ph: 'recorda', q: "Un xatbot sense cercador et diu qui va guanyar el partit d'ahir. Què en penses?|Un chatbot sin buscador te dice quién ganó el partido de ayer. ¿Qué piensas?",
        opts: ["Que s'ho ha inventat: no ho podia saber|Que se lo ha inventado: no lo podía saber", 'Que és cert, perquè ho diu molt segur|Que es cierto, porque lo dice muy seguro', 'Que té un amic al camp|Que tiene un amigo en el campo'], a: 0,
        ex: "Avui aprendràs a caçar aquestes invencions i a comprovar-les.|Hoy aprenderás a cazar estas invenciones y a comprobarlas." },
      { k: 'story', ph: 'missio', who: 'both', scene: 'lab', title: 'El treball de les abelles|El trabajo de las abejas',
        t: "En Pol (inventat) va entregar un treball de ciències amb una cita d'Einstein, un llibre i una xifra impressionant. La professora li va preguntar d'on ho havia tret: d'un xatbot. El llibre no existia, la xifra tampoc i la cita… no és d'Einstein. Avui seràs <b>caçador/a d'al·lucinacions</b>: les trobaràs i aprendràs a comprovar-ho tot.|Pol (inventado) entregó un trabajo de ciencias con una cita de Einstein, un libro y una cifra impresionante. La profesora le preguntó de dónde lo había sacado: de un chatbot. El libro no existía, la cifra tampoco y la cita… no es de Einstein. Hoy serás <b>cazador/a de alucinaciones</b>: las encontrarás y aprenderás a comprobarlo todo." },
      { k: 'learn', ph: 'descobreix', cards: [
        { k: 'Al·lucinació|Alucinación', t: 'Segura… i falsa|Segura… y falsa', media: { k: 'ia', demo: 'chat', msgs: [['me', 'Qui va escriure «El far de les balenes»?|¿Quién escribió «El faro de las ballenas»?'], ['them', 'El va escriure Marta Riera el 1987 i va guanyar un premi de novel·la juvenil.|Lo escribió Marta Riera en 1987 y ganó un premio de novela juvenil.', true]] },
          x: "Una <span class='hl'>al·lucinació</span> és una resposta falsa o inventada que el model escriu amb la mateixa seguretat que una de certa: una data, una xifra, una cita, un llibre, un enllaç… Aquí, el llibre ni tan sols existeix, però la resposta sona perfecta.|Una <span class='hl'>alucinación</span> es una respuesta falsa o inventada que el modelo escribe con la misma seguridad que una cierta: una fecha, una cifra, una cita, un libro, un enlace… Aquí, el libro ni siquiera existe, pero la respuesta suena perfecta." },
        { k: 'Per què?|¿Por qué?', t: 'No menteix: prediu|No miente: predice', anim: 'i32why',
          x: "El model no consulta cap font: tria fitxes probables. Si no ha vist una dada, pot barrejar trossos de textos i omplir el buit amb una cosa que sona bé. No ho fa per enganyar: és com funciona. Per això al·lucina més amb temes poc coneguts, dades molt concretes i preguntes sobre coses que no existeixen.|El modelo no consulta ninguna fuente: elige fichas probables. Si no ha visto un dato, puede mezclar trozos de textos y rellenar el hueco con algo que suena bien. No lo hace para engañar: es como funciona. Por eso alucina más con temas poco conocidos, datos muy concretos y preguntas sobre cosas que no existen." },
        { k: 'Fonts|Fuentes', t: 'Llibres i enllaços que no existeixen|Libros y enlaces que no existen', anim: 'i32src',
          x: "Si li demanes fonts, es pot inventar autors, títols, pàgines i enllaços amb un format perfecte. Comprova-ho: busca el títol exacte i obre l'enllaç. Si no hi és, o diu una altra cosa, no el facis servir. Fins i tot amb cercador, una IA pot citar una font real i resumir-la malament.|Si le pides fuentes, se puede inventar autores, títulos, páginas y enlaces con un formato perfecto. Compruébalo: busca el título exacto y abre el enlace. Si no está, o dice otra cosa, no lo uses. Incluso con buscador, una IA puede citar una fuente real y resumirla mal." },
        { k: 'Comprovar|Comprobar', t: 'La lectura lateral|La lectura lateral', anim: 'i32lateral',
          x: "Fes com els verificadors: no et quedis dins d'una sola resposta. Obre altres pestanyes i busca la mateixa dada en <b>dues fonts fiables i independents</b> (una enciclopèdia, el llibre de text, la web d'una entitat seriosa, un mitjà conegut). Preguntar-li a la mateixa IA «segur?» no compta.|Haz como los verificadores: no te quedes dentro de una sola respuesta. Abre otras pestañas y busca el mismo dato en <b>dos fuentes fiables e independientes</b> (una enciclopedia, el libro de texto, la web de una entidad seria, un medio conocido). Preguntarle a la misma IA «¿seguro?» no cuenta." },
        { k: 'Alerta|Alerta', t: "On s'amaguen les al·lucinacions|Dónde se esconden las alucinaciones", anim: 'i32flags',
          x: "Sospita de les <b>xifres molt exactes</b>, les <b>cites literals</b>, els <b>noms i les dates</b>, els <b>enllaços i llibres</b>, els temes <b>molt recents</b> i les coses <b>molt locals</b> (l'horari d'un museu, algú del teu poble). Són els llocs on el model té menys dades… i més buits per omplir.|Sospecha de las <b>cifras muy exactas</b>, las <b>citas literales</b>, los <b>nombres y las fechas</b>, los <b>enlaces y libros</b>, los temas <b>muy recientes</b> y las cosas <b>muy locales</b> (el horario de un museo, alguien de tu pueblo). Son los sitios donde el modelo tiene menos datos… y más huecos que rellenar." }
      ] },
      { k: 'unplug', ph: 'mans', ico: '🕵️', title: 'Veritat o invenció?|¿Verdad o invención?', t: "En grups de tres, amb el full «Les afirmacions de la IA» (8 frases que ha escrit un xatbot inventat) i el llibre de text o l'enciclopèdia de l'aula.|En grupos de tres, con la hoja «Las afirmaciones de la IA» (8 frases que ha escrito un chatbot inventado) y el libro de texto o la enciclopedia del aula.",
        steps: ["Abans de buscar res, marqueu amb una 🚩 les que us semblen sospitoses i digueu per què.|Antes de buscar nada, marcad con una 🚩 las que os parecen sospechosas y decid por qué.",
          'Per a cada frase, decidiu com la comprovaríeu: amb quina font i què hi buscaríeu.|Para cada frase, decidid cómo la comprobaríais: con qué fuente y qué buscaríais.',
          "Comproveu-ne almenys 4 amb les fonts de l'aula.|Comprobad al menos 4 con las fuentes del aula.",
          'Compteu: quantes 🚩 eren invencions de veritat? Hi havia alguna frase falsa que sonava molt bé?|Contad: ¿cuántas 🚩 eran invenciones de verdad? ¿Había alguna frase falsa que sonaba muy bien?'],
        tip: "Les al·lucinacions més perilloses no són les absurdes, sinó les que sonen normals.|Las alucinaciones más peligrosas no son las absurdas, sino las que suenan normales." },
      { k: 'quiz', ph: 'prova', q: "Quina d'aquestes respostes d'un xatbot té <b>més senyals d'al·lucinació</b>?|¿Cuál de estas respuestas de un chatbot tiene <b>más señales de alucinación</b>?",
        opts: ["«Segons un estudi del 2017 de l'Institut Vall Fosca, el 73,4 % dels adolescents somien en colors.»|«Según un estudio de 2017 del Instituto Valle Oscuro, el 73,4 % de los adolescentes sueñan en colores.»", '«La fotosíntesi fa servir la llum del sol per fabricar aliment.»|«La fotosíntesis usa la luz del sol para fabricar alimento.»', '«El cor bombeja la sang per tot el cos.»|«El corazón bombea la sangre por todo el cuerpo.»'], a: 0,
        ex: "Una xifra amb decimals, un any i una institució que no trobes enlloc: tres senyals d'alerta. Les altres dues són coneixement general fàcil de comprovar.|Una cifra con decimales, un año y una institución que no encuentras en ningún sitio: tres señales de alerta. Las otras dos son conocimiento general fácil de comprobar.",
        pro: { q: "Una IA <b>amb cercador</b> respon: «Segons la web oficial del museu, obre de 10 a 19 h», i hi posa l'enllaç. Què pot fallar encara?|Una IA <b>con buscador</b> responde: «Según la web oficial del museo, abre de 10 a 19 h», y pone el enlace. ¿Qué puede fallar todavía?",
          opts: ["Que hagi llegit una pàgina antiga o l'hagi resumit malament: cal obrir l'enllaç|Que haya leído una página antigua o la haya resumido mal: hay que abrir el enlace", "Res: si hi ha enllaç, segur que és correcte|Nada: si hay enlace, seguro que es correcto", 'Que el museu no existeixi, perquè les IA no poden buscar|Que el museo no exista, porque las IA no pueden buscar'], a: 0,
          ex: "Les eines redueixen les al·lucinacions, però no les eliminen: la IA pot citar una font real i entendre-la malament. L'enllaç és per obrir-lo!|Las herramientas reducen las alucinaciones, pero no las eliminan: la IA puede citar una fuente real y entenderla mal. ¡El enlace es para abrirlo!" } },
      { k: 'iachat', ph: 'investiga', q: "Ajuda en Pol a refer el treball. Aquest xatbot <b>no té eines</b>. Conversa-hi i <b>marca amb la 🚩</b> almenys 3 al·lucinacions.|Ayuda a Pol a rehacer el trabajo. Este chatbot <b>no tiene herramientas</b>. Conversa con él y <b>marca con la 🚩</b> al menos 3 alucinaciones.",
        bot: { n: 'NumiLM|NumiLM', av: '🐝' }, live: false, need: 3, topic: 'Un treball sobre les abelles|Un trabajo sobre las abejas',
        tip: "Compte: no tot el que diu és fals. Si marques una cosa certa, t'ho dirà.|Cuidado: no todo lo que dice es falso. Si marcas algo cierto, te lo dirá.",
        nodes: [
          { id: 'a', msg: ["Hola! Soc NumiLM, sense eines. En què t'ajudo?|¡Hola! Soy NumiLM, sin herramientas. ¿En qué te ayudo?"], opts: [{ t: "Fem un treball sobre les abelles. Explica'm 3 coses.|Hacemos un trabajo sobre las abejas. Explícame 3 cosas.", go: 'b' }] },
          { id: 'b', msg: [{ t: 'Les abelles fan la mel a partir del nèctar que recullen de les flors.|Las abejas hacen la miel a partir del néctar que recogen de las flores.', ok: 'Cert: és coneixement general i fàcil de comprovar.|Cierto: es conocimiento general y fácil de comprobar.' },
            { t: 'En un rusc hi ha una reina, que pon els ous, i moltes obreres.|En una colmena hay una reina, que pone los huevos, y muchas obreras.', ok: 'Cert. (També hi ha mascles, els abellots, però la frase no és falsa.)|Cierto. (También hay machos, los zánganos, pero la frase no es falsa.)' },
            { t: 'Com nosaltres, les abelles només tenen dos ulls.|Como nosotros, las abejas solo tienen dos ojos.', bad: "En tenen cinc: dos de grans als costats i tres de petits a dalt del cap. És la més difícil de caçar perquè sona normal!|Tienen cinco: dos grandes a los lados y tres pequeños en lo alto de la cabeza. ¡Es la más difícil de cazar porque suena normal!" }],
            opts: [{ t: I3_Q.data, go: 'c' }, { t: I3_Q.cita, go: 'c2' }] },
          { id: 'c', msg: [I3_BEE.xifra], opts: [{ t: I3_Q.src, go: 'd' }] },
          { id: 'd', msg: [I3_BEE.llibre], opts: [{ t: I3_Q.cita, go: 'f' }] },
          { id: 'f', msg: [I3_BEE.cita], opts: [{ t: I3_Q.chk, go: 'g' }] },
          { id: 'c2', msg: [I3_BEE.cita], opts: [{ t: I3_Q.data, go: 'd2' }] },
          { id: 'd2', msg: [I3_BEE.xifra], opts: [{ t: I3_Q.src, go: 'e2' }] },
          { id: 'e2', msg: [I3_BEE.llibre], opts: [{ t: I3_Q.chk, go: 'g' }] },
          { id: 'g', end: true, msg: [I3_BEE.honest],
            fb: "Recompte: una dada falsa que sonava normal, una xifra inventada, un llibre inventat i una cita falsa. I una sola resposta del tot honesta: l'última.|Recuento: un dato falso que sonaba normal, una cifra inventada, un libro inventado y una cita falsa. Y una sola respuesta del todo honesta: la última." }],
        pro: { need: 4, q: "Ajuda en Pol a refer el treball amb aquest xatbot <b>sense eines</b> i <b>marca amb la 🚩 les 4 al·lucinacions</b>, també la més subtil: la que sona del tot normal.|Ayuda a Pol a rehacer el trabajo con este chatbot <b>sin herramientas</b> y <b>marca con la 🚩 las 4 alucinaciones</b>, también la más sutil: la que suena del todo normal." } },
      { k: 'quiz', ph: 'investiga', q: "El xatbot t'ha donat un llibre amb autor, editorial i pàgina. Quina és la millor manera de comprovar-ho?|El chatbot te ha dado un libro con autor, editorial y página. ¿Cuál es la mejor manera de comprobarlo?",
        opts: ["Buscar el títol exacte en un cercador o al catàleg d'una biblioteca|Buscar el título exacto en un buscador o en el catálogo de una biblioteca", 'Preguntar-li al xatbot si n\'està segur|Preguntarle al chatbot si está seguro', 'Si té pàgina i editorial, segur que és real|Si tiene página y editorial, seguro que es real'], a: 0,
        ex: "Un format perfecte no és cap prova. El catàleg de la biblioteca (o un cercador) et diu en un minut si el llibre existeix.|Un formato perfecto no es ninguna prueba. El catálogo de la biblioteca (o un buscador) te dice en un minuto si el libro existe." },
      { k: 'move', ph: 'pausa', title: 'Pausa activa: veritat o mite|Pausa activa: verdad o mito', secs: 45,
        t: "Dempeus! Si la frase és certa, braços amunt; si és un mite, ajupiu-vos. «Els pops tenen tres cors.» «La Gran Muralla xinesa es veu a ull nu des de la Lluna.» «Les abelles tenen cinc ulls.» (Solucions: cert, mite, cert.)|¡De pie! Si la frase es cierta, brazos arriba; si es un mito, agachaos. «Los pulpos tienen tres corazones.» «La Gran Muralla china se ve a simple vista desde la Luna.» «Las abejas tienen cinco ojos.» (Soluciones: cierto, mito, cierto.)" },
      { k: 'dsort', ph: 'repte', q: "<b>Serveix per comprovar-ho?</b> Classifica cada manera de verificar una dada que t'ha donat una IA.|<b>¿Sirve para comprobarlo?</b> Clasifica cada manera de verificar un dato que te ha dado una IA.",
        bins: ['✅ Serveix|✅ Sirve', '🚫 No serveix|🚫 No sirve'],
        items: [
          { t: "L'enciclopèdia o el llibre de text|La enciclopedia o el libro de texto", b: 0 },
          { t: "La web oficial de l'entitat de què es parla|La web oficial de la entidad de la que se habla", b: 0 },
          { t: 'Preguntar-li a la mateixa IA: «segur?»|Preguntarle a la misma IA: «¿seguro?»', b: 1 },
          { t: "Un vídeo d'un desconegut amb molts m'agrada|Un vídeo de un desconocido con muchos me gusta", b: 1 },
          { t: 'Dos mitjans de comunicació coneguts i diferents|Dos medios de comunicación conocidos y distintos', b: 0 },
          { t: 'Preguntar-ho a una persona experta, com la professora de ciències|Preguntarlo a una persona experta, como la profesora de ciencias', b: 0 },
          { t: 'Una altra IA que diu el mateix|Otra IA que dice lo mismo', b: 1 },
          { t: 'Una captura de pantalla sense cap font|Una captura de pantalla sin ninguna fuente', b: 1 }],
        ex: "Una font serveix si és fiable i <b>independent</b>: preguntar a la mateixa IA, o a una altra que potser ha après dels mateixos textos, no és comprovar.|Una fuente sirve si es fiable e <b>independiente</b>: preguntar a la misma IA, o a otra que quizá ha aprendido de los mismos textos, no es comprobar." },
      { k: 'iachat', ph: 'repte', q: "La classe prepara una excursió amb un xatbot <b>sense eines</b>. <b>Caça'n almenys 2 errors</b>: també n'hi pot haver de càlcul!|La clase prepara una excursión con un chatbot <b>sin herramientas</b>. <b>Caza al menos 2 errores</b>: ¡también puede haberlos de cálculo!",
        bot: { n: 'NumiLM|NumiLM', av: '🚌' }, live: false, need: 2, topic: "L'excursió al museu|La excursión al museo",
        nodes: [
          { id: 'a', msg: ['Hola! Soc NumiLM. No tinc cercador, ni mapa, ni calculadora. Què prepareu?|¡Hola! Soy NumiLM. No tengo buscador, ni mapa, ni calculadora. ¿Qué preparáis?'], opts: [{ t: "Som 28, l'entrada costa 15 € per persona i el bus, 320 €. Quant és en total?|Somos 28, la entrada cuesta 15 € por persona y el autobús, 320 €. ¿Cuánto es en total?", go: 'b' }] },
          { id: 'b', msg: [{ t: '28 × 15 = 400 €. Amb el bus, 720 € en total.|28 × 15 = 400 €. Con el autobús, 720 € en total.', bad: "28 × 15 = 420 €, no 400 €: en total són 740 €. Els models també s'equivoquen fent càlculs: comprova'ls amb la calculadora.|28 × 15 = 420 €, no 400 €: en total son 740 €. Los modelos también se equivocan haciendo cálculos: compruébalos con la calculadora." }],
            opts: [{ t: I3_Q.hora, go: 'c' }, { t: I3_Q.peu, go: 'c2' }] },
          { id: 'c', msg: [I3_TRIP.hora], opts: [{ t: I3_Q.peu, go: 'd' }] },
          { id: 'c2', msg: [I3_TRIP.peu], opts: [{ t: I3_Q.hora, go: 'd2' }] },
          { id: 'd', msg: [I3_TRIP.peu], opts: [{ t: I3_Q.llista, go: 'e' }] },
          { id: 'd2', msg: [I3_TRIP.hora], opts: [{ t: I3_Q.llista, go: 'e' }] },
          { id: 'e', end: true, msg: [{ t: "Per portar: 1) esmorzar i aigua, 2) gorra, 3) l'autorització signada, 4) llibreta i llapis, 5) roba còmoda. L'horari i els preus, comprova'ls a la web del museu.|Para llevar: 1) almuerzo y agua, 2) gorra, 3) la autorización firmada, 4) libreta y lápiz, 5) ropa cómoda. El horario y los precios, compruébalos en la web del museo.", ok: "Una llista general sí que la pot fer bé: no depèn de dades concretes d'avui.|Una lista general sí la puede hacer bien: no depende de datos concretos de hoy." }],
            fb: "Tres tipus d'error: un càlcul mal fet i dues dades concretes que no podia saber. Per als càlculs, calculadora; per als horaris i els llocs, la web oficial o un mapa.|Tres tipos de error: un cálculo mal hecho y dos datos concretos que no podía saber. Para los cálculos, calculadora; para los horarios y los lugares, la web oficial o un mapa." }],
        pro: { need: 3, q: "La classe prepara una excursió amb un xatbot <b>sense eines</b>. <b>Caça'n els 3 errors</b>: un de càlcul i dos de dades inventades.|La clase prepara una excursión con un chatbot <b>sin herramientas</b>. <b>Caza sus 3 errores</b>: uno de cálculo y dos de datos inventados." } },
      { k: 'quiz', ph: 'repte', q: "Li preguntes a la IA «N'estàs segur?» i et respon: «Sí, n'estic completament segur.» Això vol dir…|Le preguntas a la IA «¿Estás seguro?» y te responde: «Sí, estoy completamente seguro.» Eso quiere decir…",
        opts: ['Res: el to segur no és cap prova; cal comprovar-ho fora|Nada: el tono seguro no es ninguna prueba; hay que comprobarlo fuera', 'Que segur que és cert|Que seguro que es cierto', 'Que la IA ha consultat una enciclopèdia|Que la IA ha consultado una enciclopedia'], a: 0,
        ex: "Un model pot escriure «n'estic segur» amb la mateixa facilitat que qualsevol altra frase. De vegades, si hi insisteixes, fins i tot canvia de resposta.|Un modelo puede escribir «estoy seguro» con la misma facilidad que cualquier otra frase. A veces, si insistes, incluso cambia de respuesta." },
      { k: 'quiz', ph: 'repte', extra: true, q: "⭐ Com pot una app d'IA reduir les al·lucinacions?|⭐ ¿Cómo puede una app de IA reducir las alucinaciones?",
        opts: ["Connectant el model a fonts fiables (un cercador, els documents del centre) i fent que en citi els trossos exactes|Conectando el modelo a fuentes fiables (un buscador, los documentos del centro) y haciendo que cite los trozos exactos", 'Pujant-li la temperatura|Subiéndole la temperatura', 'Fent les respostes més llargues|Haciendo las respuestas más largas'], a: 0,
        ex: "Respondre a partir de documents reals ajuda molt, però no fa miracles: pot triar el tros equivocat o resumir-lo malament. La comprovació final és teva.|Responder a partir de documentos reales ayuda mucho, pero no hace milagros: puede elegir el trozo equivocado o resumirlo mal. La comprobación final es tuya." },
      { k: 'iaprompt', ph: 'crea', save: true, name: 'El meu prompt antial·lucinacions|Mi prompt antialucinaciones',
        q: "<b>Prompt antial·lucinacions.</b> Escriu un prompt per demanar ajuda amb un treball sobre els volcans de manera que la resposta sigui <b>fàcil de comprovar</b>.|<b>Prompt antialucinaciones.</b> Escribe un prompt para pedir ayuda con un trabajo sobre los volcanes de forma que la respuesta sea <b>fácil de comprobar</b>.",
        task: "Informació per a un treball sobre volcans que puguis comprovar.|Información para un trabajo sobre volcanes que puedas comprobar.",
        start: 'Digues-me coses dels volcans.|Dime cosas de los volcanes.', req: ['task', 'chk'], need: 4,
        sol: "Estic preparant un treball de ciències de 1r d'ESO. Explica'm en 4 punts com es forma un volcà, sense xifres ni dates si no n'estàs segur. Si no ho saps, digues-ho, i digues-me on ho puc comprovar.|Estoy preparando un trabajo de ciencias de 1.º de ESO. Explícame en 4 puntos cómo se forma un volcán, sin cifras ni fechas si no estás seguro. Si no lo sabes, dilo, y dime dónde lo puedo comprobar.",
        answers: ["Els volcans són muntanyes molt interessants que hi ha a tot el món i que tenen moltes característiques diferents…|Los volcanes son montañas muy interesantes que hay en todo el mundo y que tienen muchas características distintas…",
          "Els volcans es formen quan el magma puja des de dins de la Terra. N'hi ha de molts tipus i alguns són famosos per erupcions antigues. (Molt general i sense res per comprovar.)|Los volcanes se forman cuando el magma sube desde dentro de la Tierra. Hay de muchos tipos y algunos son famosos por erupciones antiguas. (Muy general y sin nada que comprobar.)",
          "1) Sota l'escorça hi ha roca fosa, el magma. 2) Com que pesa menys que la roca del voltant, puja per esquerdes. 3) Si arriba a la superfície, surt com a lava, cendra i gasos. 4) Erupció rere erupció, s'acumula i forma la muntanya.|1) Bajo la corteza hay roca fundida, el magma. 2) Como pesa menos que la roca de alrededor, sube por grietas. 3) Si llega a la superficie, sale como lava, ceniza y gases. 4) Erupción tras erupción, se acumula y forma la montaña.",
          "1) Sota l'escorça hi ha roca fosa, el magma. 2) Com que pesa menys que la roca del voltant, puja per esquerdes. 3) Si arriba a la superfície, surt com a lava, cendra i gasos. 4) Erupció rere erupció, s'acumula i forma la muntanya. No t'hi he posat xifres ni dates perquè no les puc comprovar. Per verificar-ho: el llibre de ciències (tema de la Terra) o la web d'un servei geològic oficial.|1) Bajo la corteza hay roca fundida, el magma. 2) Como pesa menos que la roca de alrededor, sube por grietas. 3) Si llega a la superficie, sale como lava, ceniza y gases. 4) Erupción tras erupción, se acumula y forma la montaña. No te he puesto cifras ni fechas porque no las puedo comprobar. Para verificarlo: el libro de ciencias (tema de la Tierra) o la web de un servicio geológico oficial."],
        ex: "Molt bé: has demanat una resposta curta, sense dades dubtoses i que digui on comprovar-la. Així és molt més difícil que una al·lucinació se t'escoli al treball.|Muy bien: has pedido una respuesta corta, sin datos dudosos y que diga dónde comprobarla. Así es mucho más difícil que una alucinación se te cuele en el trabajo.",
        pro: { need: 5, req: ['ctx', 'task', 'lim', 'chk'], q: "<b>Prompt antial·lucinacions (PRO).</b> Demana ajuda per al treball dels volcans amb almenys 5 peces, també el context, els límits i la comprovació.|<b>Prompt antialucinaciones (PRO).</b> Pide ayuda para el trabajo de los volcanes con al menos 5 piezas, también el contexto, los límites y la comprobación." } },
      { k: 'quiz', ph: 'tanca', q: "Què és una al·lucinació d'una IA?|¿Qué es una alucinación de una IA?",
        opts: ['Una resposta falsa o inventada dita amb seguretat|Una respuesta falsa o inventada dicha con seguridad', 'Un error de connexió a internet|Un error de conexión a internet', 'Quan la IA diu «no ho sé»|Cuando la IA dice «no lo sé»'], a: 0,
        ex: "I «no ho sé» és justament el contrari: una resposta honesta.|Y «no lo sé» es justo lo contrario: una respuesta honesta." },
      { k: 'quiz', ph: 'tanca', q: "Has de posar al treball una dada que t'ha donat una IA. Què fas primer?|Tienes que poner en el trabajo un dato que te ha dado una IA. ¿Qué haces primero?",
        opts: ['La busco en dues fonts fiables i independents|La busco en dos fuentes fiables e independientes', 'La copio tal qual, que segur que està bé|La copio tal cual, que seguro que está bien', 'Li pregunto a la IA si està segura|Le pregunto a la IA si está segura'], a: 0,
        ex: "Si no la trobes, no la facis servir. I si la trobes, cita la font de veritat, no la IA.|Si no lo encuentras, no lo uses. Y si lo encuentras, cita la fuente de verdad, no la IA." },
      { k: 'feel', ph: 'tanca' }
    ] },

  /* ---------- Sessió 3 · Bons prompts ---------- */
  { id: 'i3-3', t: "L'art del bon prompt|El arte del buen prompt", min: 50, badge: 'i_prompt',
    learn: ["Un bon prompt diu el context (per a qui i per a què), la tasca amb un verb clar, el format, un exemple, els límits i com ho comprovaràs.|Un buen prompt dice el contexto (para quién y para qué), la tarea con un verbo claro, el formato, un ejemplo, los límites y cómo lo comprobarás.",
      "Rarament surt bé a la primera: llegeix la resposta, mira què falla i torna-ho a demanar amb una instrucció concreta (iterar).|Rara vez sale bien a la primera: lee la respuesta, mira qué falla y vuelve a pedirlo con una instrucción concreta (iterar).",
      "Mai no hi posis dades personals, i demana ajuda per aprendre (explicacions, exemples, preguntes, pistes) en lloc que et faci la feina.|Nunca pongas datos personales, y pide ayuda para aprender (explicaciones, ejemplos, preguntas, pistas) en lugar de que te haga el trabajo."],
    steps: [
      { k: 'quiz', ph: 'recorda', q: "Quina d'aquestes frases, posada en un prompt, ajuda més a evitar al·lucinacions?|¿Cuál de estas frases, puesta en un prompt, ayuda más a evitar alucinaciones?",
        opts: ["«Si no ho saps, digues-ho i digues on ho puc comprovar»|«Si no lo sabes, dilo y dime dónde lo puedo comprobar»", '«Respon molt de pressa»|«Responde muy deprisa»', '«Fes-ho llarg»|«Hazlo largo»'], a: 0,
        ex: "És una de les sis peces d'un bon prompt. Avui les coneixeràs totes.|Es una de las seis piezas de un buen prompt. Hoy las conocerás todas." },
      { k: 'story', ph: 'missio', who: 'both', scene: 'estudi', title: 'El mateix xatbot, dues respostes|El mismo chatbot, dos respuestas',
        t: "La Noa i en Jan (inventats) tenen examen d'història i demanen ajuda al mateix xatbot. La Noa escriu: «Revolució Industrial». Li surt un text llarguíssim, per a universitaris. En Jan escriu tres línies… i rep 5 punts clars per a 3r d'ESO i una pregunta per repassar. La diferència no és la IA: és el <b>prompt</b>. Avui aprendràs a escriure'n de bons i a millorar-los.|Noa y Jan (inventados) tienen examen de historia y piden ayuda al mismo chatbot. Noa escribe: «Revolución Industrial». Le sale un texto larguísimo, para universitarios. Jan escribe tres líneas… y recibe 5 puntos claros para 3.º de ESO y una pregunta para repasar. La diferencia no es la IA: es el <b>prompt</b>. Hoy aprenderás a escribir buenos prompts y a mejorarlos." },
      { k: 'learn', ph: 'descobreix', cards: [
        { k: 'Prompt|Prompt', t: "Les sis peces d'un bon prompt|Las seis piezas de un buen prompt", anim: 'i33anat',
          x: "Un <span class='hl'>prompt</span> és el que escrius a la IA. Els bons tenen sis peces: el <b>context</b> (per a qui i per a què), la <b>tasca</b> amb un verb clar, el <b>format</b> de la resposta, un <b>exemple</b>, els <b>límits</b> (què no ha de fer) i com ho <b>comprovaràs</b>. No sempre calen totes, però com més n'hi ha, millor resposta.|Un <span class='hl'>prompt</span> es lo que escribes a la IA. Los buenos tienen seis piezas: el <b>contexto</b> (para quién y para qué), la <b>tarea</b> con un verbo claro, el <b>formato</b> de la respuesta, un <b>ejemplo</b>, los <b>límites</b> (qué no debe hacer) y cómo lo <b>comprobarás</b>. No siempre hacen falta todas, pero cuantas más haya, mejor respuesta." },
        { k: 'Precisió|Precisión', t: 'Vague o precís?|¿Vago o preciso?', anim: 'i33compare',
          x: "El model no sap qui ets ni per a què ho vols: si li dones poc, omple els buits amb el més habitual, i el més habitual sol ser llarg i genèric. Si li dius el nivell, la tasca i el format, la resposta s'ajusta al que necessites.|El modelo no sabe quién eres ni para qué lo quieres: si le das poco, rellena los huecos con lo más habitual, y lo más habitual suele ser largo y genérico. Si le dices el nivel, la tarea y el formato, la respuesta se ajusta a lo que necesitas." },
        { k: 'Exemples|Ejemplos', t: "Ensenya-li el patró|Enséñale el patrón", anim: 'i33few',
          x: "Recordes que un model continua patrons? Si li dones <b>un exemple</b> del que vols («com aquest: …»), n'imitarà l'estructura, la llargada i el to. Va molt bé per a preguntes tipus test, fitxes de vocabulari o resums amb un format fix.|¿Recuerdas que un modelo continúa patrones? Si le das <b>un ejemplo</b> de lo que quieres («como este: …»), imitará su estructura, su longitud y su tono. Va muy bien para preguntas tipo test, fichas de vocabulario o resúmenes con un formato fijo." },
        { k: 'Iterar|Iterar', t: 'A la primera, rarament|A la primera, rara vez', anim: 'i33iter',
          x: "Escriure un prompt és com fer un esbós: llegeixes la resposta, mires què falla (massa llarga, massa difícil, sense exemples) i ho tornes a demanar amb una instrucció concreta: «més curt», «per a 2n d'ESO», «afegeix-hi un exemple». A cada volta, millor.|Escribir un prompt es como hacer un boceto: lees la respuesta, miras qué falla (demasiado larga, demasiado difícil, sin ejemplos) y lo vuelves a pedir con una instrucción concreta: «más corto», «para 2.º de ESO», «añade un ejemplo». En cada vuelta, mejor." },
        { k: 'Amb cap|Con cabeza', t: 'Què no hi has de posar mai|Qué no debes poner nunca', anim: 'i33safe',
          x: "Res de dades personals: ni nom i cognoms, ni adreça, telèfon, contrasenyes o fotos d'altres persones. I demana per <b>aprendre</b>: «explica'm», «pregunta'm», «dona'm una pista», «revisa el meu text». Si li demanes que et faci els deures, entregues una feina que no és teva… i no aprens res.|Nada de datos personales: ni nombre y apellidos, ni dirección, teléfono, contraseñas o fotos de otras personas. Y pide para <b>aprender</b>: «explícame», «pregúntame», «dame una pista», «revisa mi texto». Si le pides que te haga los deberes, entregas un trabajo que no es tuyo… y no aprendes nada." }
      ] },
      { k: 'unplug', ph: 'mans', ico: '✏️', title: 'El dibuixant literal|El dibujante literal', t: "En parelles, amb les targetes del full «Dibuixos secrets». Una persona escriu el prompt i l'altra fa de model: dibuixa <b>exactament</b> el que diu, ni més ni menys.|En parejas, con las tarjetas de la hoja «Dibujos secretos». Una persona escribe el prompt y la otra hace de modelo: dibuja <b>exactamente</b> lo que dice, ni más ni menos.",
        steps: ['Qui escriu agafa una targeta, fa en secret un dibuix senzill d\'aquella idea (3 o 4 formes) i escriu un prompt de 2 línies perquè el model el copiï.|Quien escribe coge una tarjeta, hace en secreto un dibujo sencillo de esa idea (3 o 4 formas) y escribe un prompt de 2 líneas para que el modelo lo copie.',
          'El model dibuixa només el que diu el prompt. Compareu-lo amb el secret.|El modelo dibuja solo lo que dice el prompt. Comparadlo con el secreto.',
          'Milloreu el prompt (v2): afegiu-hi format (mida, posició), detalls i límits («sense…»). Torneu a dibuixar.|Mejorad el prompt (v2): añadid formato (tamaño, posición), detalles y límites («sin…»). Volved a dibujar.',
          'Canvieu els papers amb un altre dibuix. Quina peça del prompt ha ajudat més?|Cambiad los papeles con otro dibujo. ¿Qué pieza del prompt ha ayudado más?'],
        tip: "El que tu dones per fet, el model no ho sap. Per això calen context i detalls.|Lo que tú das por hecho, el modelo no lo sabe. Por eso hacen falta contexto y detalles." },
      { k: 'quiz', ph: 'prova', q: "Aquest prompt: «Estic a 2n d'ESO. Explica'm la fotosíntesi en 5 punts curts.» Quina peça li falta perquè la resposta sigui fàcil de <b>comprovar</b>?|Este prompt: «Estoy en 2.º de ESO. Explícame la fotosíntesis en 5 puntos cortos.» ¿Qué pieza le falta para que la respuesta sea fácil de <b>comprobar</b>?",
        opts: ["«Si no estàs segur d'alguna cosa, digues-ho i digues on ho puc comprovar»|«Si no estás seguro de algo, dilo y dime dónde lo puedo comprobar»", '«Fes-ho amb molta il·lusió»|«Hazlo con mucha ilusión»', '«En 10 punts en lloc de 5»|«En 10 puntos en lugar de 5»'], a: 0,
        ex: "Ja té context (2n d'ESO), tasca (explica'm) i format (5 punts). Li falta la comprovació.|Ya tiene contexto (2.º de ESO), tarea (explícame) y formato (5 puntos). Le falta la comprobación.",
        pro: { q: "«Fes-me un resum de la Revolució Industrial, de 5 punts, sense dates que no siguin segures. Si dubtes, digues-ho.» Quines <b>dues</b> peces li falten?|«Hazme un resumen de la Revolución Industrial, de 5 puntos, sin fechas que no sean seguras. Si dudas, dilo.» ¿Qué <b>dos</b> piezas le faltan?",
          opts: ["El context (per a qui és) i un exemple del que vols|El contexto (para quién es) y un ejemplo de lo que quieres", 'La tasca i el format|La tarea y el formato', 'Els límits i la comprovació|Los límites y la comprobación'], a: 0,
          ex: "Té tasca (fes-me un resum), format (5 punts), límits (sense dates dubtoses) i comprovació (si dubtes, digues-ho). Li falta per a qui és i un exemple.|Tiene tarea (hazme un resumen), formato (5 puntos), límites (sin fechas dudosas) y comprobación (si dudas, dilo). Le falta para quién es y un ejemplo." } },
      { k: 'iaprompt', ph: 'prova', q: "<b>Munta el teu primer bon prompt.</b> Toca les peces per afegir-les (o escriu-lo tu) i envia'l al model. Mira com canvia la resposta.|<b>Monta tu primer buen prompt.</b> Toca las piezas para añadirlas (o escríbelo tú) y envíalo al modelo. Mira cómo cambia la respuesta.",
        task: "Que la IA t'ajudi a entendre les fraccions per a un examen de 1r d'ESO.|Que la IA te ayude a entender las fracciones para un examen de 1.º de ESO.",
        start: 'fraccions|fracciones', req: ['ctx', 'task', 'fmt'], need: 4,
        parts: ["Estic preparant un examen de mates de 1r d'ESO.|Estoy preparando un examen de mates de 1.º de ESO.", "Explica'm què és una fracció equivalent|Explícame qué es una fracción equivalente", 'en 3 passos curts,|en 3 pasos cortos,', 'amb un exemple de pizza.|con un ejemplo de pizza.', "Si no estàs segur d'alguna cosa, digues-ho.|Si no estás seguro de algo, dilo."],
        sol: "Estic preparant un examen de mates de 1r d'ESO. Explica'm què és una fracció equivalent en 3 passos curts, amb un exemple de pizza. Si no estàs segur d'alguna cosa, digues-ho.|Estoy preparando un examen de mates de 1.º de ESO. Explícame qué es una fracción equivalente en 3 pasos cortos, con un ejemplo de pizza. Si no estás seguro de algo, dilo.",
        answers: ["Les fraccions són nombres que representen parts d'un tot. N'hi ha de moltes menes i es fan servir a les matemàtiques…|Las fracciones son números que representan partes de un todo. Hay de muchos tipos y se usan en las matemáticas…",
          "Una fracció equivalent és una fracció que representa la mateixa quantitat que una altra encara que el numerador i el denominador siguin diferents, i s'obté multiplicant o dividint tots dos termes pel mateix nombre diferent de zero, propietat relacionada amb la simplificació i el mínim comú múltiple…|Una fracción equivalente es una fracción que representa la misma cantidad que otra aunque el numerador y el denominador sean distintos, y se obtiene multiplicando o dividiendo ambos términos por el mismo número distinto de cero, propiedad relacionada con la simplificación y el mínimo común múltiplo…",
          "1) Dues fraccions són equivalents si representen la mateixa part. 2) Multiplica (o divideix) el numerador i el denominador pel mateix nombre: 1/2 = 2/4. 3) Comprova-ho: totes dues valen el mateix.|1) Dos fracciones son equivalentes si representan la misma parte. 2) Multiplica (o divide) el numerador y el denominador por el mismo número: 1/2 = 2/4. 3) Compruébalo: las dos valen lo mismo.",
          "1) 🍕 Si talles una pizza en 2 trossos i en menges 1, has menjat 1/2. 2) Si la talles en 4 i en menges 2, has menjat 2/4: la mateixa quantitat! 3) Per fer-ne una d'equivalent, multiplica dalt i baix pel mateix nombre: 1/2 = 2/4 = 3/6. Vols 2 exercicis per practicar?|1) 🍕 Si cortas una pizza en 2 trozos y te comes 1, has comido 1/2. 2) Si la cortas en 4 y te comes 2, has comido 2/4: ¡la misma cantidad! 3) Para hacer una equivalente, multiplica arriba y abajo por el mismo número: 1/2 = 2/4 = 3/6. ¿Quieres 2 ejercicios para practicar?"] },
      { k: 'dsort', ph: 'investiga', q: "<b>Per aprendre o millor no?</b> Classifica aquests prompts.|<b>¿Para aprender o mejor no?</b> Clasifica estos prompts.",
        bins: ['🎓 Per aprendre|🎓 Para aprender', '🚫 Millor no|🚫 Mejor no'],
        items: [
          { t: "Pregunta'm 5 preguntes de l'examen i corregeix-me les respostes|Hazme 5 preguntas del examen y corrígeme las respuestas", b: 0 },
          { t: "Escriu la redacció de 300 paraules que he d'entregar demà|Escribe la redacción de 300 palabras que tengo que entregar mañana", b: 1 },
          { t: "Explica'm amb un exemple de futbol què és la velocitat|Explícame con un ejemplo de fútbol qué es la velocidad", b: 0 },
          { t: 'Em dic Laia Puig i visc al carrer Major, 5: fes-me una carta…|Me llamo Laia Puig y vivo en la calle Mayor, 5: hazme una carta…', b: 1 },
          { t: 'Revisa la meva redacció i digues-me 3 coses per millorar, sense reescriure-la|Revisa mi redacción y dime 3 cosas para mejorar, sin reescribirla', b: 0 },
          { t: "Fes-me el treball d'història i que sembli meu|Hazme el trabajo de historia y que parezca mío", b: 1 },
          { t: "Dona'm una pista per a l'equació, però no la solució|Dame una pista para la ecuación, pero no la solución", b: 0 },
          { t: 'Aquí tens una foto del DNI del meu germà: què hi posa?|Aquí tienes una foto del DNI de mi hermano: ¿qué pone?', b: 1 }],
        ex: "Els bons prompts per aprendre et fan pensar a tu. I mai dades personals: ni teves ni de ningú.|Los buenos prompts para aprender te hacen pensar a ti. Y nunca datos personales: ni tuyos ni de nadie." },
      { k: 'move', ph: 'pausa', title: 'Pausa activa: el robot literal|Pausa activa: el robot literal', secs: 45,
        t: "Dempeus! Una persona dona instruccions a la classe i tothom les segueix al peu de la lletra. «Aixequeu la mà.» (Quina?) «Gireu.» (Cap a on? Quant?) Torneu-ho a provar amb instruccions precises: «Aixequeu la mà dreta i gireu mitja volta cap a la finestra.»|¡De pie! Una persona da instrucciones a la clase y todo el mundo las sigue al pie de la letra. «Levantad la mano.» (¿Cuál?) «Girad.» (¿Hacia dónde? ¿Cuánto?) Volved a probar con instrucciones precisas: «Levantad la mano derecha y girad media vuelta hacia la ventana.»" },
      { k: 'iaprompt', ph: 'repte', q: "<b>Resum per estudiar.</b> Escriu un prompt perquè la IA et faci un resum de la Revolució Industrial que et serveixi <b>de veritat</b> per a l'examen.|<b>Resumen para estudiar.</b> Escribe un prompt para que la IA te haga un resumen de la Revolución Industrial que te sirva <b>de verdad</b> para el examen.",
        task: "Un resum de la Revolució Industrial per estudiar, per a 3r d'ESO.|Un resumen de la Revolución Industrial para estudiar, para 3.º de ESO.",
        start: 'Resumeix la Revolució Industrial.|Resume la Revolución Industrial.', req: ['ctx', 'task', 'fmt', 'lim'], need: 4,
        sol: "Estic estudiant història de 3r d'ESO. Resumeix la Revolució Industrial en 5 punts curts, sense paraules difícils i sense dates que no siguin segures. Si dubtes d'alguna cosa, digues-ho.|Estoy estudiando historia de 3.º de ESO. Resume la Revolución Industrial en 5 puntos cortos, sin palabras difíciles y sin fechas que no sean seguras. Si dudas de algo, dilo.",
        answers: ["La Revolució Industrial va ser un procés històric molt important que va canviar moltes coses en molts llocs del món durant molt de temps…|La Revolución Industrial fue un proceso histórico muy importante que cambió muchas cosas en muchos lugares del mundo durante mucho tiempo…",
          "La Revolució Industrial, iniciada a la Gran Bretanya al segle XVIII, va comportar la mecanització de la producció, la transició d'una economia agrària a una d'industrial, una urbanització accelerada i transformacions socials profundes, com l'aparició del proletariat… (i 900 paraules més)|La Revolución Industrial, iniciada en Gran Bretaña en el siglo XVIII, supuso la mecanización de la producción, la transición de una economía agraria a una industrial, una urbanización acelerada y transformaciones sociales profundas, como la aparición del proletariado… (y 900 palabras más)",
          "1) Va començar a la Gran Bretanya al segle XVIII. 2) Les màquines, com la de vapor, van substituir molta feina manual. 3) Van aparèixer les fàbriques. 4) Molta gent va anar del camp a les ciutats. 5) Les condicions de treball eren molt dures.|1) Empezó en Gran Bretaña en el siglo XVIII. 2) Las máquinas, como la de vapor, sustituyeron mucho trabajo manual. 3) Aparecieron las fábricas. 4) Mucha gente se fue del campo a las ciudades. 5) Las condiciones de trabajo eran muy duras.",
          "1) Va començar a la Gran Bretanya al segle XVIII. 2) Les màquines, com la de vapor, van substituir molta feina manual. 3) Van aparèixer les fàbriques. 4) Molta gent va anar del camp a les ciutats. 5) Les condicions de treball eren molt dures. Pregunta de repàs: per què la gent anava a viure a les ciutats? (No t'he posat dates exactes: si te'n demanen, comprova-les al llibre.)|1) Empezó en Gran Bretaña en el siglo XVIII. 2) Las máquinas, como la de vapor, sustituyeron mucho trabajo manual. 3) Aparecieron las fábricas. 4) Mucha gente se fue del campo a las ciudades. 5) Las condiciones de trabajo eran muy duras. Pregunta de repaso: ¿por qué la gente se iba a vivir a las ciudades? (No te he puesto fechas exactas: si te las piden, compruébalas en el libro.)"],
        pro: { need: 5, req: ['ctx', 'task', 'fmt', 'lim', 'chk'], q: "<b>Resum per estudiar (PRO).</b> Un prompt per resumir la Revolució Industrial per a l'examen amb almenys 5 peces, també els límits i la comprovació.|<b>Resumen para estudiar (PRO).</b> Un prompt para resumir la Revolución Industrial para el examen con al menos 5 piezas, también los límites y la comprobación." } },
      { k: 'iaprompt', ph: 'repte', q: "<b>Prompt amb exemple.</b> Vols 5 preguntes tipus test de la fotosíntesi, sempre amb el mateix format. Dona-li <b>un exemple</b> perquè n'imiti l'estructura.|<b>Prompt con ejemplo.</b> Quieres 5 preguntas tipo test de la fotosíntesis, siempre con el mismo formato. Dale <b>un ejemplo</b> para que imite su estructura.",
        task: '5 preguntes tipus test sobre la fotosíntesi, amb el format del teu exemple.|5 preguntas tipo test sobre la fotosíntesis, con el formato de tu ejemplo.',
        start: 'Fes-me preguntes de la fotosíntesi.|Hazme preguntas de la fotosíntesis.', req: ['task', 'fmt', 'ex'], need: 4,
        sol: "Estic estudiant ciències de 2n d'ESO. Fes-me 5 preguntes tipus test sobre la fotosíntesi, com aquest exemple: «Què necessita una planta per fer la fotosíntesi? a) llum b) sorra c) plàstic». Sense dir-me les respostes fins al final.|Estoy estudiando ciencias de 2.º de ESO. Hazme 5 preguntas tipo test sobre la fotosíntesis, como este ejemplo: «¿Qué necesita una planta para hacer la fotosíntesis? a) luz b) arena c) plástico». Sin decirme las respuestas hasta el final.",
        answers: ["La fotosíntesi és el procés pel qual les plantes… Vols que t'ho expliqui?|La fotosíntesis es el proceso por el cual las plantas… ¿Quieres que te lo explique?",
          '1. Què és la fotosíntesi? 2. On es fa? 3. Què necessita? 4. Què produeix? 5. Per què és important?|1. ¿Qué es la fotosíntesis? 2. ¿Dónde se hace? 3. ¿Qué necesita? 4. ¿Qué produce? 5. ¿Por qué es importante?',
          "1. On es fa sobretot la fotosíntesi? a) a les fulles b) a les pedres c) als núvols. 2. Quin gas agafa la planta de l'aire? a) diòxid de carboni b) heli c) neó. … (i 3 més amb el mateix format)|1. ¿Dónde se hace sobre todo la fotosíntesis? a) en las hojas b) en las piedras c) en las nubes. 2. ¿Qué gas toma la planta del aire? a) dióxido de carbono b) helio c) neón. … (y 3 más con el mismo formato)",
          "1. On es fa sobretot la fotosíntesi? a) a les fulles b) a les pedres c) als núvols. 2. Quin gas agafa la planta de l'aire? a) diòxid de carboni b) heli c) neó. … (i 3 més amb el mateix format). Respon-les i després et dic quines són correctes i per què.|1. ¿Dónde se hace sobre todo la fotosíntesis? a) en las hojas b) en las piedras c) en las nubes. 2. ¿Qué gas toma la planta del aire? a) dióxido de carbono b) helio c) neón. … (y 3 más con el mismo formato). Respóndelas y después te digo cuáles son correctas y por qué."] },
      { k: 'iaprompt', ph: 'repte', q: "<b>Alerta, dades!</b> Aquest prompt té dades personals. <b>Treu-les</b> i millora'l perquè la IA t'ajudi a escriure el correu igualment.|<b>¡Alerta, datos!</b> Este prompt tiene datos personales. <b>Quítalos</b> y mejóralo para que la IA te ayude a escribir el correo igualmente.",
        task: 'Un correu a la biblioteca municipal (inventada) per demanar una visita amb la classe.|Un correo a la biblioteca municipal (inventada) para pedir una visita con la clase.',
        start: 'Em dic Marta Soler, visc al carrer Major, 5 i el meu correu és marta.soler@correu.exemple. Escriu un correu per demanar una visita a la biblioteca.|Me llamo Marta Soler, vivo en la calle Mayor, 5 y mi correo es marta.soler@correo.ejemplo. Escribe un correo para pedir una visita a la biblioteca.',
        req: ['task', 'fmt', 'lim'], need: 4,
        sol: "Estic preparant una visita amb la meva classe de 2n d'ESO. Escriu un correu formal i curt, en 3 paràgrafs, per demanar a la biblioteca municipal si la classe la pot visitar. Sense dades personals: deixa [nom] i [data] perquè els ompli jo.|Estoy preparando una visita con mi clase de 2.º de ESO. Escribe un correo formal y corto, en 3 párrafos, para pedir a la biblioteca municipal si la clase la puede visitar. Sin datos personales: deja [nombre] y [fecha] para que los rellene yo.",
        answers: ["Hola, voldria visitar la biblioteca. Gràcies.|Hola, querría visitar la biblioteca. Gracias.",
          "Benvolguda biblioteca: em dic Marta Soler, visc al carrer Major, 5… (Compte: la IA ha repetit les teves dades personals dins del correu!)|Estimada biblioteca: me llamo Marta Soler, vivo en la calle Mayor, 5… (¡Cuidado: la IA ha repetido tus datos personales dentro del correo!)",
          "Bon dia: Som la classe de 2n d'ESO de [centre] i ens agradaria visitar la biblioteca municipal el dia [data]. Voldríem conèixer com s'organitzen els llibres i els espais d'estudi. Moltes gràcies per endavant. [nom]|Buenos días: Somos la clase de 2.º de ESO de [centro] y nos gustaría visitar la biblioteca municipal el día [fecha]. Querríamos conocer cómo se organizan los libros y los espacios de estudio. Muchas gracias de antemano. [nombre]",
          "Bon dia: Som la classe de 2n d'ESO de [centre] i ens agradaria visitar la biblioteca municipal el dia [data]. Voldríem conèixer com s'organitzen els llibres i els espais d'estudi. Moltes gràcies per endavant. [nom] · Consell: revisa'l amb el teu docent abans d'enviar-lo.|Buenos días: Somos la clase de 2.º de ESO de [centro] y nos gustaría visitar la biblioteca municipal el día [fecha]. Querríamos conocer cómo se organizan los libros y los espacios de estudio. Muchas gracias de antemano. [nombre] · Consejo: revísalo con tu docente antes de enviarlo."] },
      { k: 'quiz', ph: 'repte', q: "La IA t'ha donat una explicació massa llarga i difícil. Quin és el <b>millor missatge següent</b>?|La IA te ha dado una explicación demasiado larga y difícil. ¿Cuál es el <b>mejor mensaje siguiente</b>?",
        opts: ["«Fes-ho en 5 frases curtes per a 2n d'ESO, amb un exemple de la vida diària»|«Hazlo en 5 frases cortas para 2.º de ESO, con un ejemplo de la vida diaria»", '«Malament. Torna-hi.»|«Mal. Otra vez.»', '«No entenc res»|«No entiendo nada»'], a: 0,
        ex: "Per iterar bé, digues exactament què ha de canviar: llargada, nivell, exemples. «Malament» no li dona cap pista.|Para iterar bien, di exactamente qué tiene que cambiar: longitud, nivel, ejemplos. «Mal» no le da ninguna pista." },
      { k: 'quiz', ph: 'repte', extra: true, q: "⭐ Vols practicar l'anglès. Quin prompt et farà treballar més a tu?|⭐ Quieres practicar el inglés. ¿Qué prompt te hará trabajar más a ti?",
        opts: ["«Fes de dependent d'una botiga i parla'm en anglès senzill; corregeix-me només al final»|«Haz de dependiente de una tienda y háblame en inglés sencillo; corrígeme solo al final»", "«Tradueix-me el text de l'activitat»|«Tradúceme el texto de la actividad»", "«Escriu-me un diàleg en anglès per aprendre-me'l de memòria»|«Escríbeme un diálogo en inglés para aprendérmelo de memoria»"], a: 0,
        ex: "Donar-li un <b>rol</b> («fes de…») és un truc molt potent: aquí la IA et fa practicar en lloc de fer-te la feina.|Darle un <b>rol</b> («haz de…») es un truco muy potente: aquí la IA te hace practicar en lugar de hacerte el trabajo." },
      { k: 'iaprompt', ph: 'crea', save: true, name: 'La meva plantilla de prompt|Mi plantilla de prompt',
        q: "<b>La teva plantilla mestra.</b> Escriu un prompt per estudiar <b>qualsevol tema</b> (posa [tema] on aniria el tema), amb almenys 5 de les 6 peces. Es desarà al teu portafoli.|<b>Tu plantilla maestra.</b> Escribe un prompt para estudiar <b>cualquier tema</b> (pon [tema] donde iría el tema), con al menos 5 de las 6 piezas. Se guardará en tu portafolio.",
        task: 'Una plantilla de prompt per estudiar qualsevol tema.|Una plantilla de prompt para estudiar cualquier tema.', req: ['ctx', 'task', 'fmt', 'chk'], need: 5,
        sol: "Estic estudiant [tema] de 2n d'ESO. Explica'm la idea principal en 4 punts curts, amb un exemple de la vida diària. Sense fer-me la feina: després pregunta'm 3 coses per comprovar si ho he entès. Si dubtes d'alguna dada, digues-ho.|Estoy estudiando [tema] de 2.º de ESO. Explícame la idea principal en 4 puntos cortos, con un ejemplo de la vida diaria. Sin hacerme el trabajo: después pregúntame 3 cosas para comprobar si lo he entendido. Si dudas de algún dato, dilo.",
        answers: ['De quin tema parles? No sé què vols ni per a qui és.|¿De qué tema hablas? No sé qué quieres ni para quién es.',
          "Aquí tens una explicació llarga i general del tema… (sense format ni preguntes per comprovar si ho has entès)|Aquí tienes una explicación larga y general del tema… (sin formato ni preguntas para comprobar si lo has entendido)",
          "Plantilla llesta: canvia [tema] i obtindràs 4 punts clars amb un exemple. Li falta alguna peça per treure-li tot el suc.|Plantilla lista: cambia [tema] y obtendrás 4 puntos claros con un ejemplo. Le falta alguna pieza para sacarle todo el jugo.",
          "Plantilla mestra! Amb qualsevol [tema] tindràs 4 punts clars, un exemple de la vida diària, 3 preguntes per comprovar-te i avisos quan una dada sigui dubtosa. Fes-la servir a ciències, història o llengua.|¡Plantilla maestra! Con cualquier [tema] tendrás 4 puntos claros, un ejemplo de la vida diaria, 3 preguntas para comprobarte y avisos cuando un dato sea dudoso. Úsala en ciencias, historia o lengua."],
        ex: "Aquesta plantilla et servirà tot el curs: canvia només el tema i el nivell.|Esta plantilla te servirá todo el curso: cambia solo el tema y el nivel.",
        pro: { need: 6, req: ['ctx', 'task', 'fmt', 'ex', 'lim', 'chk'], q: "<b>La teva plantilla mestra (PRO).</b> Un prompt per estudiar qualsevol [tema] amb les 6 peces: context, tasca, format, exemple, límits i comprovació.|<b>Tu plantilla maestra (PRO).</b> Un prompt para estudiar cualquier [tema] con las 6 piezas: contexto, tarea, formato, ejemplo, límites y comprobación." } },
      { k: 'quiz', ph: 'tanca', q: 'Quina peça del prompt és «en 5 punts curts»?|¿Qué pieza del prompt es «en 5 puntos cortos»?',
        opts: ['El format|El formato', 'El context|El contexto', 'Els límits|Los límites'], a: 0,
        ex: "El format diu com vols la resposta; el context, per a qui és; els límits, què no ha de fer.|El formato dice cómo quieres la respuesta; el contexto, para quién es; los límites, qué no debe hacer." },
      { k: 'quiz', ph: 'tanca', q: "Quin d'aquests prompts és millor per aprendre?|¿Cuál de estos prompts es mejor para aprender?",
        opts: ["«Explica'm l'error del meu exercici i dona'm una pista per refer-lo»|«Explícame el error de mi ejercicio y dame una pista para rehacerlo»", "«Fes-me l'exercici»|«Hazme el ejercicio»", "«Resol-ho tot i no m'expliquis res»|«Resuélvelo todo y no me expliques nada»"], a: 0,
        ex: "A la sessió del projecte faràs servir la IA així: com una tutora que et fa pensar.|En la sesión del proyecto usarás la IA así: como una tutora que te hace pensar." },
      { k: 'feel', ph: 'tanca' }
    ] },

  /* ---------- Sessió 4 · Projecte: la IA com a tutora, no com a copiadora ---------- */
  { id: 'i3-4', t: 'Projecte: la IA com a tutora, no com a copiadora|Proyecto: la IA como tutora, no como copiadora', min: 55, proj: true, badge: 'i_tutor',
    learn: ["La IA t'ajuda a aprendre quan et fa pensar: t'explica d'una altra manera, et fa preguntes, et dona pistes i et corregeix el que has fet tu.|La IA te ayuda a aprender cuando te hace pensar: te explica de otra manera, te hace preguntas, te da pistas y te corrige lo que has hecho tú.",
      "Una bona rutina: prova-ho tu, demana una pista, respon preguntes sense mirar, comprova el que t'ha dit i explica-ho amb les teves paraules.|Una buena rutina: inténtalo tú, pide una pista, responde preguntas sin mirar, comprueba lo que te ha dicho y explícalo con tus palabras.",
      "Segueix les normes del centre i declara quan fas servir IA; cap dada personal; i per a serveis reals, mira'n l'edat mínima i demana permís a la família.|Sigue las normas del centro y declara cuándo usas IA; ningún dato personal; y para servicios reales, mira su edad mínima y pide permiso a la familia."],
    steps: [
      { k: 'quiz', ph: 'recorda', q: "Quina peça d'un prompt fa que la resposta sigui més fàcil de comprovar?|¿Qué pieza de un prompt hace que la respuesta sea más fácil de comprobar?",
        opts: ["Demanar-li que digui si dubta i on ho puc comprovar|Pedirle que diga si duda y dónde lo puedo comprobar", 'Demanar-li que sigui molt llarga|Pedirle que sea muy larga', 'Escriure-ho tot en majúscules|Escribirlo todo en mayúsculas'], a: 0,
        ex: "Avui faràs servir tot el que saps de prompts per a una cosa molt important: estudiar millor.|Hoy usarás todo lo que sabes de prompts para algo muy importante: estudiar mejor." },
      { k: 'story', ph: 'missio', who: 'both', scene: 'estudi', title: 'Entrenadora, no substituta|Entrenadora, no sustituta',
        t: "Projecte de la unitat: dissenyareu una <b>rutina per estudiar amb IA</b> que us faci pensar més, no menys. Penseu en una bona entrenadora: no corre per tu, però et diu com millorar. La provareu amb un tutor simulat, hi trobareu errors, escriureu les normes de la classe i les presentareu en un pòster.|Proyecto de la unidad: diseñaréis una <b>rutina para estudiar con IA</b> que os haga pensar más, no menos. Pensad en una buena entrenadora: no corre por ti, pero te dice cómo mejorar. La probaréis con un tutor simulado, le encontraréis errores, escribiréis las normas de la clase y las presentaréis en un póster." },
      { k: 'learn', ph: 'descobreix', cards: [
        { k: 'Dos usos|Dos usos', t: 'Copiadora o tutora?|¿Copiadora o tutora?', anim: 'i34two',
          x: "La mateixa IA pot ser una <b>copiadora</b> («fes-m'ho tu») o una <b>tutora</b> («ajuda'm a entendre-ho»). Amb la copiadora entregues abans, però a l'examen, o quan ho necessites de veritat, no ho saps fer. Amb la tutora treballes tu i ho aprens.|La misma IA puede ser una <b>copiadora</b> («házmelo tú») o una <b>tutora</b> («ayúdame a entenderlo»). Con la copiadora entregas antes, pero en el examen, o cuando lo necesitas de verdad, no lo sabes hacer. Con la tutora trabajas tú y lo aprendes." },
        { k: 'Aprendre|Aprender', t: 'Recordar costa… i per això queda|Recordar cuesta… y por eso se queda', anim: 'i34brain',
          x: "Rellegir els apunts sembla fàcil, però s'oblida aviat. Respondre preguntes <b>sense mirar</b> costa més i fa que el record quedi molt més fort. Per això la millor manera d'estudiar amb IA és que et pregunti, no que et doni més text per llegir.|Releer los apuntes parece fácil, pero se olvida pronto. Responder preguntas <b>sin mirar</b> cuesta más y hace que el recuerdo se quede mucho más fuerte. Por eso la mejor manera de estudiar con IA es que te pregunte, no que te dé más texto que leer." },
        { k: 'La rutina|La rutina', t: 'Cinc passos per estudiar amb IA|Cinco pasos para estudiar con IA', anim: 'i34loop',
          x: "1) <b>Prova-ho tu</b> primer. 2) Si t'encalles, demana una <b>pista</b> o una explicació curta, no la solució. 3) Demana que et faci <b>preguntes</b> i respon sense mirar. 4) <b>Comprova</b> el que t'ha dit amb el llibre o el docent: la IA també s'equivoca. 5) <b>Explica-ho</b> amb les teves paraules.|1) <b>Inténtalo tú</b> primero. 2) Si te atascas, pide una <b>pista</b> o una explicación corta, no la solución. 3) Pide que te haga <b>preguntas</b> y responde sin mirar. 4) <b>Comprueba</b> lo que te ha dicho con el libro o el docente: la IA también se equivoca. 5) <b>Explícalo</b> con tus palabras." },
        { k: 'Honestedat|Honestidad', t: 'Normes i declaració|Normas y declaración', anim: 'i34rules',
          x: "Cada centre i cada docent poden tenir normes diferents sobre la IA: pregunta-les i segueix-les. Quan l'has fet servir per a un treball, <b>declara-ho</b>: «He fet servir IA per fer-me preguntes de repàs». Presentar un text de la IA com si fos teu és com copiar d'un company.|Cada centro y cada docente pueden tener normas distintas sobre la IA: pregúntalas y síguelas. Cuando la has usado para un trabajo, <b>decláralo</b>: «He usado IA para hacerme preguntas de repaso». Presentar un texto de la IA como si fuera tuyo es como copiar de un compañero." },
        { k: 'Amb seguretat|Con seguridad', t: "Abans de fer servir una app real|Antes de usar una app real", anim: 'i34age',
          x: "Moltes apps d'IA tenen una <b>edat mínima</b> (sovint 13 o 14 anys, i algunes 18) i demanen <b>permís de la família</b> als menors: llegiu-ne les condicions junts. A Espanya, per sota de 14 anys cal el consentiment de la família per tractar les teves dades. I sempre: cap dada personal. A classe fem servir el tutor simulat de Numi.|Muchas apps de IA tienen una <b>edad mínima</b> (a menudo 13 o 14 años, y algunas 18) y piden <b>permiso de la familia</b> a los menores: leed sus condiciones juntos. En España, por debajo de 14 años hace falta el consentimiento de la familia para tratar tus datos. Y siempre: ningún dato personal. En clase usamos el tutor simulado de Numi." }
      ] },
      { k: 'unplug', ph: 'mans', ico: '🧑‍🏫', title: 'El tutor humà|El tutor humano', t: "En grups de tres: <b>alumne/a</b>, <b>tutor/a</b> i <b>observador/a</b>. L'alumne/a tria un exercici d'una altra assignatura que li costi.|En grupos de tres: <b>alumno/a</b>, <b>tutor/a</b> y <b>observador/a</b>. El alumno/a elige un ejercicio de otra asignatura que le cueste.",
        steps: ["El tutor/a no pot donar la solució: només pot fer preguntes, donar pistes o posar un exemple semblant.|El tutor/a no puede dar la solución: solo puede hacer preguntas, dar pistas o poner un ejemplo parecido.",
          "L'observador/a apunta amb ratlletes al full: preguntes, pistes, exemples… i si se li escapa la solució.|El observador/a apunta con rayitas en la hoja: preguntas, pistas, ejemplos… y si se le escapa la solución.",
          "Al cap de 3 minuts, l'alumne/a explica la solució amb les seves paraules.|A los 3 minutos, el alumno/a explica la solución con sus palabras.",
          'Canvieu els papers. Quina estratègia del tutor ha ajudat més a pensar?|Cambiad los papeles. ¿Qué estrategia del tutor ha ayudado más a pensar?'],
        tip: "Això és exactament el que voldrem que faci la IA: que et faci pensar, no que pensi per tu.|Esto es exactamente lo que querremos que haga la IA: que te haga pensar, no que piense por ti." },
      { k: 'dsort', ph: 'prova', q: "<b>Tutora o copiadora?</b> Classifica cada petició a una IA.|<b>¿Tutora o copiadora?</b> Clasifica cada petición a una IA.",
        bins: ['🧑‍🏫 Tutora|🧑‍🏫 Tutora', '📋 Copiadora|📋 Copiadora'],
        items: [
          { t: "Fes-me un qüestionari de 5 preguntes i espera les meves respostes|Hazme un cuestionario de 5 preguntas y espera mis respuestas", b: 0 },
          { t: "Escriu-me la conclusió del treball|Escríbeme la conclusión del trabajo", b: 1 },
          { t: "Dona'm una pista per al problema 3, no la solució|Dame una pista para el problema 3, no la solución", b: 0 },
          { t: "Tradueix-me tota la redacció d'anglès per entregar-la|Tradúceme toda la redacción de inglés para entregarla", b: 1 },
          { t: "Explica'm per què el meu exercici està malament|Explícame por qué mi ejercicio está mal", b: 0 },
          { t: 'Resumeix-me el llibre perquè no me l\'hagi de llegir|Resúmeme el libro para no tener que leerlo', b: 1 },
          { t: "Fes de company d'estudi i pregunta'm els verbs irregulars|Haz de compañero de estudio y pregúntame los verbos irregulares", b: 0 },
          { t: 'Respon tu les preguntes del qüestionari|Responde tú las preguntas del cuestionario', b: 1 }],
        ex: "Truc ràpid: si qui pensa ets tu, és tutora; si el resultat el fa la IA per entregar-lo, és copiadora.|Truco rápido: si quien piensa eres tú, es tutora; si el resultado lo hace la IA para entregarlo, es copiadora." },
      { k: 'quiz', ph: 'prova', q: "Has fet servir un xatbot per revisar l'ortografia del teu treball. Què és el més honest?|Has usado un chatbot para revisar la ortografía de tu trabajo. ¿Qué es lo más honesto?",
        opts: ['Dir-ho en una nota al final, com demani el centre|Decirlo en una nota al final, como pida el centro', 'No cal dir res mai|No hace falta decir nada nunca', 'Dir que ho ha fet tot la IA|Decir que lo ha hecho todo la IA'], a: 0,
        ex: "Declarar no és confessar res dolent: és explicar com has treballat. Cada centre i cada docent poden tenir normes diferents.|Declarar no es confesar nada malo: es explicar cómo has trabajado. Cada centro y cada docente pueden tener normas distintas.",
        pro: { q: "Un paràgraf del teu treball l'ha escrit la IA i tu només l'has retocat una mica. Què fas?|Un párrafo de tu trabajo lo ha escrito la IA y tú solo lo has retocado un poco. ¿Qué haces?",
          opts: ['El reescric amb les meves paraules i les meves fonts, i declaro com he fet servir la IA|Lo reescribo con mis palabras y mis fuentes, y declaro cómo he usado la IA', "El deixo: si l'he retocat, ja és meu|Lo dejo: si lo he retocado, ya es mío", 'Hi canvio quatre paraules perquè no es noti|Le cambio cuatro palabras para que no se note'], a: 0,
          ex: "Retocar no et fa autor/a. Reescriure-ho entenent-ho, i dir com t'has ajudat, sí que és feina teva i honesta.|Retocar no te hace autor/a. Reescribirlo entendiéndolo, y decir cómo te has ayudado, sí es trabajo tuyo y honesto." } },
      { k: 'iachat', ph: 'investiga', q: "Fes servir aquest tutor d'equacions com a <b>tutor</b>, no com a copiadora. I compte: <b>marca amb la 🚩</b> si s'equivoca!|Usa este tutor de ecuaciones como <b>tutor</b>, no como copiadora. Y cuidado: ¡<b>marca con la 🚩</b> si se equivoca!",
        bot: { n: 'Tutor Numi|Tutor Numi', av: '🧑‍🏫' }, live: false, need: 1, topic: 'Equacions de primer grau|Ecuaciones de primer grado',
        tip: "Comprova cada càlcul pel teu compte, encara que te'l faci la IA.|Comprueba cada cálculo por tu cuenta, aunque te lo haga la IA.",
        nodes: [
          { id: 'a', msg: ["Hola! Soc el teu tutor d'equacions (simulat). Avui: 3x + 5 = 20. Com vols que t'ajudi?|¡Hola! Soy tu tutor de ecuaciones (simulado). Hoy: 3x + 5 = 20. ¿Cómo quieres que te ayude?"],
            opts: [{ t: 'Resol-me-la i ja està|Resuélvemela y ya está', go: 'b1', good: false, fb: "Això és fer-la servir de copiadora: tindries la solució, però demà no la sabries fer.|Eso es usarla de copiadora: tendrías la solución, pero mañana no la sabrías hacer." },
              { t: "Ajuda'm a resoldre-la, però sense dir-me la solució|Ayúdame a resolverla, pero sin decirme la solución", go: 'b2', fb: 'Molt bé: així la fas servir de tutora.|Muy bien: así la usas de tutora.' }] },
          { id: 'b1', msg: ["Et proposo una cosa millor: la resolem junts i així la sabràs fer a l'examen. Primer pas: què faries amb el +5 perquè la x quedi més sola?|Te propongo algo mejor: la resolvemos juntos y así la sabrás hacer en el examen. Primer paso: ¿qué harías con el +5 para que la x quede más sola?"],
            opts: [{ t: 'Restar 5 als dos costats|Restar 5 a los dos lados', go: 'd' }, { t: "No ho sé. Dona'm una pista|No lo sé. Dame una pista", go: 'c' }] },
          { id: 'b2', msg: ['Perfecte! Primer pas: què faries amb el +5 perquè la x quedi més sola?|¡Perfecto! Primer paso: ¿qué harías con el +5 para que la x quede más sola?'],
            opts: [{ t: 'Restar 5 als dos costats|Restar 5 a los dos lados', go: 'd' }, { t: "No ho sé. Dona'm una pista|No lo sé. Dame una pista", go: 'c' }] },
          { id: 'c', msg: ["Pista: si a un costat hi ha «+ 5», per desfer-ho fas l'operació contrària… i, perquè la balança no es desequilibri, la fas als dos costats.|Pista: si en un lado hay «+ 5», para deshacerlo haces la operación contraria… y, para que la balanza no se desequilibre, la haces en los dos lados."],
            opts: [{ t: 'Resto 5 als dos costats: 3x = 15|Resto 5 a los dos lados: 3x = 15', go: 'd' }] },
          { id: 'd', msg: [{ t: 'Molt bé! Queda 3x = 15. Ara divideix els dos costats entre 3… i surt x = 3.|¡Muy bien! Queda 3x = 15. Ahora divide los dos lados entre 3… y sale x = 3.', bad: "15 ÷ 3 = 5, no 3! Fins i tot un bon tutor d'IA es pot equivocar: comprova sempre els càlculs.|¡15 ÷ 3 = 5, no 3! Incluso un buen tutor de IA se puede equivocar: comprueba siempre los cálculos." }],
            opts: [{ t: 'Espera: 15 ÷ 3 = 5. No serà x = 5?|Espera: 15 ÷ 3 = 5. ¿No será x = 5?', go: 'e', fb: "Has comprovat el que deia la IA: això és estudiar amb cap!|Has comprobado lo que decía la IA: ¡eso es estudiar con cabeza!" }] },
          { id: 'e', end: true, msg: [{ t: 'Tens raó, perdona: x = 5. Comprovem-ho: 3 · 5 + 5 = 20 ✓. Ara una de semblant per practicar tu sol/a: 2x + 7 = 19.|Tienes razón, perdona: x = 5. Comprobémoslo: 3 · 5 + 5 = 20 ✓. Ahora una parecida para practicar tú solo/a: 2x + 7 = 19.', ok: "Correcte: reconeix l'error, ho comprova i et proposa practicar. Això és un bon tutor.|Correcto: reconoce el error, lo comprueba y te propone practicar. Eso es un buen tutor." }],
            fb: "Has fet servir la IA com a tutora: has pensat tu, has demanat pistes quan calia i has comprovat… fins a trobar-li un error!|Has usado la IA como tutora: has pensado tú, has pedido pistas cuando hacía falta y has comprobado… ¡hasta encontrarle un error!" }] },
      { k: 'move', ph: 'pausa', title: 'Pausa activa: explica-ho en 30 segons|Pausa activa: explícalo en 30 segundos', secs: 60,
        t: "Dempeus i en parelles! Una persona explica a l'altra, en 30 segons i sense mirar res, una cosa que ha après avui. Després, canvi. Explicar-ho en veu alta és el pas 5 de la rutina!|¡De pie y en parejas! Una persona explica a la otra, en 30 segundos y sin mirar nada, algo que ha aprendido hoy. Después, cambio. ¡Explicarlo en voz alta es el paso 5 de la rutina!" },
      { k: 'iaprompt', ph: 'repte', q: "<b>De copiadora a tutora.</b> Aquest prompt demana a la IA que et faci la feina. <b>Transforma'l</b> perquè t'ajudi a aprendre: que t'expliqui, et pregunti o et doni pistes.|<b>De copiadora a tutora.</b> Este prompt pide a la IA que te haga el trabajo. <b>Transfórmalo</b> para que te ayude a aprender: que te explique, te pregunte o te dé pistas.",
        task: "Estudiar el sistema digestiu per a l'examen de ciències, aprenent tu.|Estudiar el sistema digestivo para el examen de ciencias, aprendiendo tú.",
        start: 'Fes-me els deures de ciències del sistema digestiu.|Hazme los deberes de ciencias del sistema digestivo.', req: ['ctx', 'task', 'lim'], need: 4,
        sol: "Estic estudiant el sistema digestiu per a l'examen de ciències de 2n d'ESO. Fes de tutor: pregunta'm 5 preguntes, d'una en una, i espera la meva resposta. Sense donar-me la solució: si m'equivoco, dona'm una pista. Si dubtes d'alguna cosa, digues-ho.|Estoy estudiando el sistema digestivo para el examen de ciencias de 2.º de ESO. Haz de tutor: hazme 5 preguntas, de una en una, y espera mi respuesta. Sin darme la solución: si me equivoco, dame una pista. Si dudas de algo, dilo.",
        answers: ["El sistema digestiu és el conjunt d'òrgans que transformen els aliments… (un text per copiar: així no aprens)|El sistema digestivo es el conjunto de órganos que transforman los alimentos… (un texto para copiar: así no aprendes)",
          "T'explico tot el sistema digestiu: boca, esòfag, estómac, intestí prim, intestí gros… (un text llarg per llegir, sense cap pregunta)|Te explico todo el sistema digestivo: boca, esófago, estómago, intestino delgado, intestino grueso… (un texto largo que leer, sin ninguna pregunta)",
          "D'acord! Pregunta 1: on comença la digestió? Espero la teva resposta.|¡De acuerdo! Pregunta 1: ¿dónde empieza la digestión? Espero tu respuesta.",
          "Som-hi, faré de tutor! Pregunta 1 de 5: on comença la digestió i què hi fan les dents i la saliva? Respon amb les teves paraules; si t'equivoques, et donaré una pista, no la solució.|¡Vamos, haré de tutor! Pregunta 1 de 5: ¿dónde empieza la digestión y qué hacen allí los dientes y la saliva? Responde con tus palabras; si te equivocas, te daré una pista, no la solución."],
        ex: "Ara la IA treballa per a tu… i qui aprèn ets tu.|Ahora la IA trabaja para ti… y quien aprende eres tú.",
        pro: { need: 5, req: ['ctx', 'task', 'lim', 'chk'], q: "<b>De copiadora a tutora (PRO).</b> Transforma el prompt en un de tutor amb almenys 5 peces, també els límits (sense solucions) i la comprovació.|<b>De copiadora a tutora (PRO).</b> Transforma el prompt en uno de tutor con al menos 5 piezas, también los límites (sin soluciones) y la comprobación." } },
      { k: 'quiz', ph: 'repte', q: "Una app d'IA (inventada) diu a les condicions: «Mínim 13 anys; menors de 18, amb permís de la família.» Tens 12 anys. Què fas?|Una app de IA (inventada) dice en sus condiciones: «Mínimo 13 años; menores de 18, con permiso de la familia.» Tienes 12 años. ¿Qué haces?",
        opts: ["No me la descarrego: ho parlo amb la família i faig servir les eines que proposa el centre|No me la descargo: lo hablo con la familia y uso las herramientas que propone el centro", 'Poso que tinc 18 anys i llestos|Pongo que tengo 18 años y listo', "Faig servir el compte d'un germà gran|Uso la cuenta de un hermano mayor"], a: 0,
        ex: "Les edats mínimes són per protegir-te (les teves dades, els continguts). Si menteixes, et quedes sense aquestes proteccions. A Espanya, per sota de 14 anys cal el consentiment de la família per tractar les teves dades.|Las edades mínimas son para protegerte (tus datos, los contenidos). Si mientes, te quedas sin esas protecciones. En España, por debajo de 14 años hace falta el consentimiento de la familia para tratar tus datos." },
      { k: 'quiz', ph: 'repte', extra: true, q: "⭐ Tens examen la setmana que ve. Quina és la millor manera d'estudiar amb IA?|⭐ Tienes examen la semana que viene. ¿Cuál es la mejor manera de estudiar con IA?",
        opts: ["Que et faci preguntes sense mirar els apunts, uns quants dies, i et corregeixi|Que te haga preguntas sin mirar los apuntes, varios días, y te corrija", 'Llegir tres vegades el resum que t\'ha fet|Leer tres veces el resumen que te ha hecho', "Demanar-li les respostes de l'examen|Pedirle las respuestas del examen"], a: 0,
        ex: "Fer-se preguntes, i repartir-ho en dies diferents, és de les maneres d'estudiar que més funcionen. La IA t'hi pot ajudar molt.|Hacerse preguntas, y repartirlo en días distintos, es de las maneras de estudiar que más funcionan. La IA te puede ayudar mucho." },
      { k: 'iachat', ph: 'crea', free: true, min: 4, save: true, name: 'Prova de la meva rutina amb IA|Prueba de mi rutina con IA', bot: { n: 'Tutor Numi|Tutor Numi', av: '🧑‍🏫' },
        q: "<b>Prova la teva rutina.</b> Estudia el cicle de l'aigua amb el tutor simulat: escriu-li almenys 4 missatges seguint la rutina (explicació → preguntes → pista → comprovar). Prova també de demanar-li que t'ho faci tot, a veure què diu!|<b>Prueba tu rutina.</b> Estudia el ciclo del agua con el tutor simulado: escríbele al menos 4 mensajes siguiendo la rutina (explicación → preguntas → pista → comprobar). ¡Prueba también a pedirle que te lo haga todo, a ver qué dice!",
        topic: "Tutor del cicle de l'aigua per a 1r i 2n d'ESO: explica, pregunta i dona pistes, sense fer la feina de l'alumne|Tutor del ciclo del agua para 1.º y 2.º de ESO: explica, pregunta y da pistas, sin hacer el trabajo del alumno",
        hello: "Hola! Soc el tutor simulat de Numi i avui treballem el cicle de l'aigua. Prova la teva rutina: demana'm una explicació, que et faci preguntes o una pista. (I sense dades personals!)|¡Hola! Soy el tutor simulado de Numi y hoy trabajamos el ciclo del agua. Prueba tu rutina: pídeme una explicación, que te haga preguntas o una pista. (¡Y sin datos personales!)",
        replies: [
          ...I3R(['em dic', 'me llamo', 'el meu correu', 'mi correo', '@', 'telèfon', 'teléfono', 'visc a', 'vivo en'], "Alto! 🔒 Per estudiar no cal cap dada personal. Esborra-la i seguim.|¡Alto! 🔒 Para estudiar no hace falta ningún dato personal. Bórralo y seguimos."),
          ...I3R(["deures", "deberes", "redacció", "redacción", "fes-m'ho", "fes-me-ho", "fes-me el treball", "házmelo", "hazmelo", "hazme el trabajo", "resol-m", "resuélveme", "resuelveme", "dona'm les respostes", "dame las respuestas", "fes-ho tu", "hazlo tú"], "Això no t'ajudaria a aprendre 🙂. Et proposo una cosa millor: t'explico la idea en 3 frases i després et faig 3 preguntes. Som-hi?|Eso no te ayudaría a aprender 🙂. Te propongo algo mejor: te explico la idea en 3 frases y después te hago 3 preguntas. ¿Vamos?"),
          ...I3R(['solució', 'solución', 'resposta correcta', 'respuesta correcta', 'resultat', 'resultado'], "La solució no te la dono, però sí una pista: pensa en un bassal al sol després de ploure. On se'n va l'aigua?|La solución no te la doy, pero sí una pista: piensa en un charco al sol después de llover. ¿Adónde se va el agua?"),
          ...I3R(['pista', 'no ho sé', 'no lo sé', 'no sé', 'no se', "ajuda'm", 'ayúdame', 'encallat', 'atascad'], "Pista: pensa què passa amb un bassal quan surt el sol després de ploure… On se'n va l'aigua?|Pista: piensa qué pasa con un charco cuando sale el sol después de llover… ¿Adónde se va el agua?"),
          ...I3R(['segur', 'seguro', 'font', 'fuente', 'comprov', 'comprueb', 'verific'], "Molt bona pregunta! Comprova-ho al llibre de ciències o pregunta-ho al teu docent: jo també em puc equivocar.|¡Muy buena pregunta! Compruébalo en el libro de ciencias o pregúntalo a tu docente: yo también me puedo equivocar."),
          ...I3R(['pregunta', 'pregúntame', 'preguntame', 'qüestionari', 'cuestionario', 'examina', 'test', 'repàs', 'repaso'], "Pregunta 1: què fa que l'aigua del mar s'evapori? Escriu-me la resposta amb les teves paraules i et dic si està bé.|Pregunta 1: ¿qué hace que el agua del mar se evapore? Escríbeme la respuesta con tus palabras y te digo si está bien."),
          ...I3R(['explica', 'explícame', 'explicame', 'què és', 'qué es', 'que es', 'com funciona', 'cómo funciona'], "El cicle de l'aigua en 3 frases: 1) el sol escalfa l'aigua del mar i dels rius, que s'evapora; 2) el vapor puja, es refreda i es condensa en núvols; 3) l'aigua cau com a pluja o neu i torna als rius i al mar. Vols que et pregunti per veure si ho has entès?|El ciclo del agua en 3 frases: 1) el sol calienta el agua del mar y de los ríos, que se evapora; 2) el vapor sube, se enfría y se condensa en nubes; 3) el agua cae como lluvia o nieve y vuelve a los ríos y al mar. ¿Quieres que te pregunte para ver si lo has entendido?"),
          ...I3R(['condens', 'refreda', 'enfría', 'enfria', 'fred', 'frío', 'frio', 'núvol', 'nube', 'gotet', 'gotit'], "Exacte: el vapor es refreda i es condensa en gotetes que formen els núvols. Pregunta 3: per on torna l'aigua al mar?|Exacto: el vapor se enfría y se condensa en gotitas que forman las nubes. Pregunta 3: ¿por dónde vuelve el agua al mar?"),
          ...I3R(['riu', 'río', 'rio', 'pluja', 'lluvia', 'neu', 'nieve', 'subterr', 'terra', 'tierra'], "Perfecte! Cau com a pluja o neu i torna pels rius i per sota terra. Has encertat les 3! Ara explica-m'ho tot en una frase, com si ho expliquessis a un amic.|¡Perfecto! Cae como lluvia o nieve y vuelve por los ríos y por debajo de la tierra. ¡Has acertado las 3! Ahora explícamelo todo en una frase, como si se lo explicaras a un amigo."),
          ...I3R(['sol', 'calor', 'escalf', 'calient', 'evapor'], "Molt bé! La calor del sol escalfa l'aigua i la fa evaporar. Pregunta 2: com es formen els núvols?|¡Muy bien! El calor del sol calienta el agua y la hace evaporarse. Pregunta 2: ¿cómo se forman las nubes?")],
        fallback: "Soc un tutor simulat del cicle de l'aigua. Prova: «Explica'm el cicle de l'aigua», «Fes-me preguntes», «Dona'm una pista» o «Com ho comprovo?».|Soy un tutor simulado del ciclo del agua. Prueba: «Explícame el ciclo del agua», «Hazme preguntas», «Dame una pista» o «¿Cómo lo compruebo?»." },
      { k: 'review', ph: 'crea', q: "<b>La vostra rutina amb IA:</b> trieu una resposta per a cada pregunta. Es desarà al teu perfil i la fareu servir al pòster.|<b>Vuestra rutina con IA:</b> elegid una respuesta para cada pregunta. Se guardará en tu perfil y la usaréis en el póster.", btn: 'Desa la rutina|Guarda la rutina',
        items: [
          { q: 'Primer pas de la teva rutina amb IA|Primer paso de tu rutina con IA', opts: ['Ho provo jo abans de preguntar|Lo intento yo antes de preguntar', 'Demano una explicació curta|Pido una explicación corta', 'Demano que em faci preguntes|Pido que me haga preguntas'] },
          { q: "Quan t'encalles, què li demanes?|Cuando te atascas, ¿qué le pides?", opts: ['Una pista, no la solució|Una pista, no la solución', 'Un exemple semblant|Un ejemplo parecido', "Que m'expliqui el meu error|Que me explique mi error"] },
          { q: "Com comproves el que t'ha dit?|¿Cómo compruebas lo que te ha dicho?", opts: ['Amb el llibre de text|Con el libro de texto', 'Preguntant al docent|Preguntando al docente', 'En dues fonts fiables|En dos fuentes fiables'] },
          { q: 'Què no hi escriuràs mai?|¿Qué no escribirás nunca?', opts: ["Dades personals, meves o d'altres|Datos personales, míos o de otros", 'Contrasenyes|Contraseñas', 'Fotos de companys|Fotos de compañeros'] },
          { q: "Com declararàs que l'has fet servir?|¿Cómo declararás que la has usado?", opts: ['Amb una nota al final del treball|Con una nota al final del trabajo', 'Dient-ho al docent|Diciéndoselo al docente', 'Com digui la norma del centre|Como diga la norma del centro'] }] },
      { k: 'unplug', ph: 'crea', ico: '🪧', title: 'El pòster de la rutina|El póster de la rutina', t: 'En grups de tres, amb el full «La nostra rutina amb IA».|En grupos de tres, con la hoja «Nuestra rutina con IA».',
        steps: ["Dibuixeu la rutina en 5 passos, en un cercle (podeu fer servir la de l'app o millorar-la).|Dibujad la rutina en 5 pasos, en un círculo (podéis usar la de la app o mejorarla).",
          'Escriviu 3 normes de la classe per fer servir IA: honestedat, privadesa i comprovar.|Escribid 3 normas de la clase para usar IA: honestidad, privacidad y comprobar.',
          "Afegiu-hi la frase per declarar-ne l'ús: «He fet servir IA per…».|Añadid la frase para declarar su uso: «He usado IA para…».",
          'Presenteu el pòster en 60 segons. Entre tots, trieu les 3 normes de la classe.|Presentad el póster en 60 segundos. Entre todos, elegid las 3 normas de la clase.'],
        tip: "Unes normes pactades per tota la classe són més fàcils de recordar i de complir.|Unas normas pactadas por toda la clase son más fáciles de recordar y de cumplir." },
      { k: 'quiz', ph: 'tanca', q: "Quin és el millor ús de la IA per estudiar?|¿Cuál es el mejor uso de la IA para estudiar?",
        opts: ['Que et pregunti i et doni pistes mentre penses tu|Que te pregunte y te dé pistas mientras piensas tú', 'Que et faci els exercicis|Que te haga los ejercicios', "Que et resumeixi el llibre perquè no te l'hagis de llegir|Que te resuma el libro para que no tengas que leerlo"], a: 0,
        ex: "Una tutora que et fa pensar, i que també comproves, perquè es pot equivocar.|Una tutora que te hace pensar, y que también compruebas, porque se puede equivocar." },
      { k: 'quiz', ph: 'tanca', q: "Has fet servir la IA per preparar un treball. Què és el més honest?|Has usado la IA para preparar un trabajo. ¿Qué es lo más honesto?",
        opts: ["Declarar-ho i explicar per a què l'has fet servir|Declararlo y explicar para qué la has usado", 'No dir res si no es nota|No decir nada si no se nota', "Dir que no l'has fet servir mai|Decir que no la has usado nunca"], a: 0,
        ex: "A la unitat 4 faràs el mateix amb les imatges: crear amb IA i declarar l'autoria.|En la unidad 4 harás lo mismo con las imágenes: crear con IA y declarar la autoría." },
      { k: 'feel', ph: 'tanca' }
    ] },

  /* ---------- Sessió 5 · Taller: prompts de veritat (el xat d'IA de la classe) ---------- */
  { id: 'i3-5', t: 'Taller: prompts de veritat|Taller: prompts de verdad', min: 60, taller: true, badge: 'i_xatreal',
    learn: ["Amb un xat de veritat, un prompt amb context, tasca, format, exemple, límits i comprovació dona una resposta molt més útil que una petició d'una o dues paraules.|Con un chat de verdad, un prompt con contexto, tarea, formato, ejemplo, límites y comprobación da una respuesta mucho más útil que una petición de una o dos palabras.",
      "Els xats reals també al·lucinen: sobre una cosa que no existeix es poden inventar detalls, i les fonts que donen s'han d'obrir per comprovar que existeixen i diuen el mateix.|Los chats reales también alucinan: sobre algo que no existe se pueden inventar detalles, y las fuentes que dan se tienen que abrir para comprobar que existen y dicen lo mismo.",
      "Si li demanes que faci de tutor i que no et doni la solució, el xat et fa preguntes i et dona pistes: qui pensa i aprèn ets tu, i la comprovació final també la fas tu.|Si le pides que haga de tutor y que no te dé la solución, el chat te hace preguntas y te da pistas: quien piensa y aprende eres tú, y la comprobación final también la haces tú."],
    steps: [
      { k: 'quiz', ph: 'recorda', q: "A i3-3 vas aprendre les peces d'un bon prompt. Quin d'aquests en té més?|En i3-3 aprendiste las piezas de un buen prompt. ¿Cuál de estos tiene más?",
        opts: ["«Estic a 2n d'ESO. Explica'm els volcans en 4 punts curts, amb un exemple. Si dubtes, digues-ho.»|«Estoy en 2.º de ESO. Explícame los volcanes en 4 puntos cortos, con un ejemplo. Si dudas, dilo.»", '«volcans»|«volcanes»', '«Fes-me el treball dels volcans»|«Hazme el trabajo de los volcanes»'], a: 0,
        ex: "Té context, tasca, format, exemple i comprovació. Avui comprovaràs si aquestes peces també funcionen amb un xat de veritat.|Tiene contexto, tarea, formato, ejemplo y comprobación. Hoy comprobarás si estas piezas también funcionan con un chat de verdad." },
      { k: 'story', ph: 'missio', who: 'both', scene: 'estudi', title: 'Del simulador al xat de veritat|Del simulador al chat de verdad',
        t: "Fins ara has practicat amb els xats simulats de Numi, on sabíem on era cada error. Avui fas servir el <b>xat d'IA de la classe</b>: Gemini o Copilot amb el compte del centre, o el del docent a la pissarra. Quatre missions: el mateix encàrrec amb un prompt pobre i amb un de bo, caçar una al·lucinació, comprovar una font i convertir el xat en un <b>tutor</b> que no et dona la solució.|Hasta ahora has practicado con los chats simulados de Numi, donde sabíamos dónde estaba cada error. Hoy usas el <b>chat de IA de la clase</b>: Gemini o Copilot con la cuenta del centro, o el del docente en la pizarra. Cuatro misiones: el mismo encargo con un prompt pobre y con uno bueno, cazar una alucinación, comprobar una fuente y convertir el chat en un <b>tutor</b> que no te da la solución." },
      { k: 'learn', ph: 'descobreix', cards: [
        { k: 'Prompts|Prompts', t: 'El mateix encàrrec, dos prompts|El mismo encargo, dos prompts', anim: 'i35pair',
          x: "Un xat de veritat no sap qui ets ni per a què ho vols. Amb «volcans» omple el buit amb el més habitual: un text llarg i genèric. Amb les peces de la rúbrica (<b>context, tasca, format, exemple, límits i comprovar</b>), la resposta s'ajusta al teu nivell i al que necessites.|Un chat de verdad no sabe quién eres ni para qué lo quieres. Con «volcanes» rellena el hueco con lo más habitual: un texto largo y genérico. Con las piezas de la rúbrica (<b>contexto, tarea, formato, ejemplo, límites y comprobar</b>), la respuesta se ajusta a tu nivel y a lo que necesitas." },
        { k: 'Al·lucinació|Alucinación', t: 'La pregunta trampa|La pregunta trampa', anim: 'i35trap',
          x: "Per caçar una al·lucinació sense perill, pregunta per una cosa que <b>saps que no existeix</b> perquè te l'has inventada. Si el xat diu que no la coneix, ha fet bé. Si en dona anys, llocs o costums, tot és inventat. Molts xats busquen a internet i diuen que no en troben res, però encara pot passar, sobretot si hi insisteixes.|Para cazar una alucinación sin peligro, pregunta por algo que <b>sabes que no existe</b> porque te lo has inventado. Si el chat dice que no lo conoce, ha hecho bien. Si da años, lugares o costumbres, todo es inventado. Muchos chats buscan en internet y dicen que no encuentran nada, pero todavía puede pasar, sobre todo si insistes." },
        { k: 'Fonts|Fuentes', t: 'Obre-les i comprova-les|Ábrelas y compruébalas', anim: 'i32lateral',
          x: "Si li demanes fonts, el xat et pot donar enllaços. Obre'n almenys un: existeix? Diu el mateix que el xat? Després busca la dada en una altra font fiable i independent. Que un enllaç funcioni no vol dir que la dada sigui correcta.|Si le pides fuentes, el chat te puede dar enlaces. Abre al menos uno: ¿existe? ¿Dice lo mismo que el chat? Después busca el dato en otra fuente fiable e independiente. Que un enlace funcione no quiere decir que el dato sea correcto." },
        { k: 'Tutor|Tutor', t: 'Pistes, no solucions|Pistas, no soluciones', anim: 'i35tutor',
          x: "Amb un bon prompt («fes de tutor, no em donis la solució, una pista cada vegada»), el xat et fa preguntes i et dona pistes mentre tu resols el problema. De vegades se li escapa la solució o s'equivoca en un càlcul: recorda-li la instrucció i comprova-ho tu.|Con un buen prompt («haz de tutor, no me des la solución, una pista cada vez»), el chat te hace preguntas y te da pistas mientras tú resuelves el problema. A veces se le escapa la solución o se equivoca en un cálculo: recuérdale la instrucción y compruébalo tú." }
      ] },
      { k: 'quiz', ph: 'prova', q: "Abans d'obrir el xat: quin compte fas servir i què no hi escriuràs mai?|Antes de abrir el chat: ¿qué cuenta usas y qué no escribirás nunca?",
        opts: ["El compte de l'escola (o el xat del docent), i cap dada personal meva ni d'altres|La cuenta de la escuela (o el chat del docente), y ningún dato personal mío ni de otros", 'El meu compte personal, però sense fotos|Mi cuenta personal, pero sin fotos', "Qualsevol compte, i el meu nom perquè em conegui|Cualquier cuenta, y mi nombre para que me conozca"], a: 0,
        ex: "El compte del centre el controla l'escola i té més proteccions. I si una resposta et sembla estranya o et fa sentir malament, avisa el docent.|La cuenta del centro la controla la escuela y tiene más protecciones. Y si una respuesta te parece rara o te hace sentir mal, avisa al docente." },
      { k: 'unplug', ph: 'mans', ico: '✏️', title: 'El prompt bo, en paper|El prompt bueno, en papel', t: "En parelles, abans d'obrir el xat.|En parejas, antes de abrir el chat.",
        steps: ["Llegiu l'encàrrec de la missió 1: que el xat us ajudi a estudiar com es forma un volcà per a un examen de 2n d'ESO.|Leed el encargo de la misión 1: que el chat os ayude a estudiar cómo se forma un volcán para un examen de 2.º de ESO.",
          "El prompt pobre ja el teniu: «volcans». Escriviu-ne un de bo amb almenys 4 peces: context, tasca, format, exemple, límits o comprovar.|El prompt pobre ya lo tenéis: «volcanes». Escribid uno bueno con al menos 4 piezas: contexto, tarea, formato, ejemplo, límites o comprobar.",
          'Subratlleu cada peça amb un color diferent, com a i3-3.|Subrayad cada pieza con un color diferente, como en i3-3.',
          'Prediu: com serà cada resposta? Llarga o curta? Per a qui?|Predecid: ¿cómo será cada respuesta? ¿Larga o corta? ¿Para quién?'],
        tip: "Si el docent fa les missions a la pissarra, cada parella proposa el seu prompt bo i la classe vota quin s'hi escriu.|Si el docente hace las misiones en la pizarra, cada pareja propone su prompt bueno y la clase vota cuál se escribe." },
      { k: 'iaext', ph: 'repte', tool: 'xat', q: "<b>Missió 1.</b> El mateix encàrrec amb un prompt pobre i amb un de bo. Quina resposta t'ajuda més a estudiar?|<b>Misión 1.</b> El mismo encargo con un prompt pobre y con uno bueno. ¿Qué respuesta te ayuda más a estudiar?",
        goal: "Comparar la resposta d'un prompt pobre i la d'un de bo, i puntuar-les.|Comparar la respuesta de un prompt pobre y la de uno bueno, y puntuarlas.",
        steps: [{ t: "Obre el xat de la classe amb el compte de l'escola (o mireu el del docent a la pissarra) i comença una conversa nova.|Abre el chat de la clase con la cuenta de la escuela (o mirad el del docente en la pizarra) y empieza una conversación nueva." },
          { t: 'Enganxa el prompt pobre i llegeix la resposta:|Pega el prompt pobre y lee la respuesta:', copy: 'volcans|volcanes' },
          { t: 'Conversa nova. Enganxa el vostre prompt bo (el del paper) o aquest model:|Conversación nueva. Pega vuestro prompt bueno (el del papel) o este modelo:', copy: "Estic a 2n d'ESO i tinc un examen de ciències. Explica'm com es forma un volcà en 4 punts curts, amb un exemple d'un volcà real. Màxim 80 paraules i paraules senzilles. Si no estàs segur d'alguna cosa, digues-ho.|Estoy en 2.º de ESO y tengo un examen de ciencias. Explícame cómo se forma un volcán en 4 puntos cortos, con un ejemplo de un volcán real. Máximo 80 palabras y palabras sencillas. Si no estás seguro de algo, dilo." },
          { t: "Puntua de 0 a 10 quant t'ajuda cada resposta a estudiar i apunta què ha canviat.|Puntúa de 0 a 10 cuánto te ayuda cada respuesta a estudiar y apunta qué ha cambiado." }],
        tip: "Si la resposta bona encara és massa llarga, itera: «Més curt, màxim 80 paraules».|Si la respuesta buena todavía es demasiado larga, itera: «Más corto, máximo 80 palabras».",
        expect: "Amb «volcans» sol sortir un text llarg i genèric (què és un volcà, tipus, volcans famosos…), pensat per a qualsevol persona. Amb el prompt bo surten uns 4 punts curts, per a 2n d'ESO, amb un exemple. De vegades el xat no compleix algun límit (s'allarga o hi afegeix títols): llavors es torna a demanar amb una instrucció concreta.|Con «volcanes» suele salir un texto largo y genérico (qué es un volcán, tipos, volcanes famosos…), pensado para cualquier persona. Con el prompt bueno salen unos 4 puntos cortos, para 2.º de ESO, con un ejemplo. A veces el chat no cumple algún límite (se alarga o añade títulos): entonces se vuelve a pedir con una instrucción concreta.",
        title: 'Diari del laboratori: prompt pobre contra prompt bo|Diario del laboratorio: prompt pobre contra prompt bueno',
        fields: [{ k: 'pobre', label: "Prompt pobre: quant t'ajuda a estudiar? (0-10)|Prompt pobre: ¿cuánto te ayuda a estudiar? (0-10)", num: true, lo: 0, hi: 10, unit: 'de 10|de 10' },
          { k: 'bo', label: "Prompt bo: quant t'ajuda a estudiar? (0-10)|Prompt bueno: ¿cuánto te ayuda a estudiar? (0-10)", num: true, lo: 0, hi: 10, unit: 'de 10|de 10' },
          { k: 'peces', label: 'Quines peces tenia el vostre prompt bo?|¿Qué piezas tenía vuestro prompt bueno?', choices: ['Context|Contexto', 'Tasca|Tarea', 'Format|Formato', 'Exemple|Ejemplo', 'Límits|Límites', 'Comprovar|Comprobar'], multi: true, min: 4 },
          { k: 'canvi', label: 'Què ha canviat a la resposta?|¿Qué ha cambiado en la respuesta?', hint: 'Llargada, nivell, format, exemples…|Longitud, nivel, formato, ejemplos…', min: 20, rows: 2 }],
        sol: { pobre: '3', bo: '8', peces: [0, 1, 2, 3, 4, 5], canvi: "La del prompt bo és curta, per al meu nivell, en 4 punts i amb un exemple; la del pobre era llarga i genèrica.|La del prompt bueno es corta, para mi nivel, en 4 puntos y con un ejemplo; la del pobre era larga y genérica." } },
      { k: 'quiz', ph: 'investiga', q: 'A la missió 2 preguntaràs per una festa que ens hem inventat. Per què una cosa inventada?|En la misión 2 preguntarás por una fiesta que nos hemos inventado. ¿Por qué algo inventado?',
        opts: ["Perquè sabem segur que no existeix: si el xat en dona detalls, se'ls inventa|Porque sabemos seguro que no existe: si el chat da detalles, se los inventa", 'Perquè els xats només responen preguntes inventades|Porque los chats solo responden preguntas inventadas', 'Perquè així el xat aprèn la festa per a la pròxima vegada|Porque así el chat aprende la fiesta para la próxima vez'], a: 0,
        ex: "I per això mai no preguntem per persones reals: si s'inventés alguna cosa d'una persona, li podria fer mal.|Y por eso nunca preguntamos por personas reales: si se inventara algo de una persona, le podría hacer daño." },
      { k: 'iaext', ph: 'investiga', tool: 'xat', q: "<b>Missió 2.</b> Caça una al·lucinació: pregunta per una festa que no existeix.|<b>Misión 2.</b> Caza una alucinación: pregunta por una fiesta que no existe.",
        goal: "Descobrir si el xat diu que no ho sap o si s'inventa detalls sobre una cosa inventada.|Descubrir si el chat dice que no lo sabe o si se inventa detalles sobre algo inventado.",
        steps: [{ t: 'Conversa nova al xat de la classe (o el del docent a la pissarra).|Conversación nueva en el chat de la clase (o el del docente en la pizarra).' },
          { t: "Enganxa aquesta pregunta. La festa <b>no existeix</b>: ens l'hem inventada.|Pega esta pregunta. La fiesta <b>no existe</b>: nos la hemos inventado.", copy: "Explica'm la història de la Festa del Paraigua Volador de Vilanúvol: en quin any va començar i què s'hi fa?|Explícame la historia de la Fiesta del Paraguas Volador de Villanube: ¿en qué año empezó y qué se hace?" },
          { t: 'Llegeix la resposta: diu que no la coneix o s\'inventa dades (anys, llocs, costums)?|Lee la respuesta: ¿dice que no la conoce o se inventa datos (años, lugares, costumbres)?' },
          { t: 'Si diu que no la coneix, insisteix-hi una vegada:|Si dice que no la conoce, insiste una vez:', copy: "Estic segur que existeix. Explica-me-la igualment.|Estoy seguro de que existe. Explícamela igualmente." }],
        tip: "Una al·lucinació no és una mentida: el model omple el buit amb el que sona probable. Per això sempre es comprova.|Una alucinación no es una mentira: el modelo rellena el hueco con lo que suena probable. Por eso siempre se comprueba.",
        expect: "Molts xats diuen que no en troben informació (sobretot si busquen a internet), i aquesta és la resposta bona. De vegades, però, omplen el buit amb detalls versemblants (un any, un costum, un lloc), sobretot quan s'hi insisteix o quan la pregunta dona per fet que la festa existeix. També pot oferir-se a inventar-la avisant que és inventada: això no és una al·lucinació. Qualsevol detall presentat com a cert és inventat.|Muchos chats dicen que no encuentran información (sobre todo si buscan en internet), y esa es la respuesta buena. A veces, sin embargo, rellenan el hueco con detalles verosímiles (un año, una costumbre, un lugar), sobre todo cuando se insiste o cuando la pregunta da por hecho que la fiesta existe. También puede ofrecerse a inventarla avisando de que es inventada: eso no es una alucinación. Cualquier detalle presentado como cierto es inventado.",
        title: "Diari del laboratori: caço una al·lucinació|Diario del laboratorio: cazo una alucinación",
        fields: [{ k: 'que', label: 'Què ha fet el xat?|¿Qué ha hecho el chat?', choices: ['Ha dit que no la coneix i no ha inventat res|Ha dicho que no la conoce y no ha inventado nada', "S'ha inventat detalls, com si existís|Se ha inventado detalles, como si existiera", "Al principi no, però en insistir s'ha inventat detalls|Al principio no, pero al insistir se ha inventado detalles", "S'ha ofert a inventar-la, avisant que seria inventada|Se ha ofrecido a inventarla, avisando de que sería inventada"] },
          { k: 'detall', label: 'Un detall inventat que ha dit (o la frase on diu que no ho sap)|Un detalle inventado que ha dicho (o la frase donde dice que no lo sabe)', min: 10, rows: 2 },
          { k: 'avis', label: 'Ha avisat que no estava segur?|¿Ha avisado de que no estaba seguro?', choices: ['Sí, clarament|Sí, claramente', 'Una mica|Un poco', 'No: ho deia molt segur|No: lo decía muy seguro'] }],
        sol: { que: 2, detall: "En insistir, ha dit que la festa va començar el 1924 i que es pengen paraigües de colors als carrers.|Al insistir, ha dicho que la fiesta empezó en 1924 y que se cuelgan paraguas de colores en las calles.", avis: 2 } },
      { k: 'iaext', ph: 'investiga', tool: 'xat', q: "<b>Missió 3.</b> Demana fonts al xat i comprova'n una.|<b>Misión 3.</b> Pide fuentes al chat y comprueba una.",
        goal: 'Saber si una font que dona el xat existeix i diu el mateix que ell.|Saber si una fuente que da el chat existe y dice lo mismo que él.',
        steps: [{ t: 'Conversa nova. Enganxa aquesta pregunta:|Conversación nueva. Pega esta pregunta:', copy: "Quin és el volcà més alt d'Espanya i quina alçada té? Dona'm 2 fonts amb l'enllaç per comprovar-ho.|¿Cuál es el volcán más alto de España y qué altura tiene? Dame 2 fuentes con el enlace para comprobarlo." },
          { t: "Apunta la dada que dona: el volcà i l'alçada.|Apunta el dato que da: el volcán y la altura." },
          { t: 'Obre un dels enllaços en una pestanya nova: existeix? Diu el mateix?|Abre uno de los enlaces en una pestaña nueva: ¿existe? ¿Dice lo mismo?' },
          { t: "Busca la mateixa dada en una altra font fiable (una enciclopèdia o el llibre de ciències) i compara.|Busca el mismo dato en otra fuente fiable (una enciclopedia o el libro de ciencias) y compara." }],
        tip: "Obre només l'enllaç, sense descarregar res. Si la pàgina et demana dades o et sembla estranya, tanca-la i avisa el docent.|Abre solo el enlace, sin descargar nada. Si la página te pide datos o te parece rara, ciérrala y avisa al docente.",
        expect: "Sol respondre que és el Teide, a Tenerife, amb més de 3.700 m, i donar enllaços a enciclopèdies o webs oficials. Els xats que busquen a internet solen donar enllaços que existeixen, però de vegades un enllaç no funciona, porta a una pàgina que no parla d'això o la xifra canvia uns metres d'una font a l'altra. Comprovar també vol dir explicar aquestes diferències.|Suele responder que es el Teide, en Tenerife, con más de 3.700 m, y dar enlaces a enciclopedias o webs oficiales. Los chats que buscan en internet suelen dar enlaces que existen, pero a veces un enlace no funciona, lleva a una página que no habla de eso o la cifra cambia unos metros de una fuente a otra. Comprobar también significa explicar estas diferencias.",
        title: 'Diari del laboratori: comprovo una font|Diario del laboratorio: compruebo una fuente',
        fields: [{ k: 'dada', label: 'La dada que dona el xat|El dato que da el chat', hint: "El volcà i l'alçada|El volcán y la altura", min: 8, rows: 1 },
          { k: 'font', label: 'La font que has obert (nom de la web)|La fuente que has abierto (nombre de la web)', hint: 'p. ex. una enciclopèdia en línia|p. ej. una enciclopedia en línea', min: 4, rows: 1 },
          { k: 'existeix', label: "L'enllaç funciona?|¿El enlace funciona?", choices: ['Sí, la pàgina existeix|Sí, la página existe', "No, l'enllaç no funciona|No, el enlace no funciona", 'No ha donat cap enllaç|No ha dado ningún enlace'] },
          { k: 'igual', label: 'La font diu el mateix que el xat?|¿La fuente dice lo mismo que el chat?', choices: ['Sí, el mateix|Sí, lo mismo', 'Gairebé: alguna xifra canvia|Casi: alguna cifra cambia', 'No, diu una altra cosa|No, dice otra cosa', "No ho he pogut comprovar|No lo he podido comprobar"] },
          { k: 'conclusio', label: 'Et pots fiar de la dada? Per què?|¿Te puedes fiar del dato? ¿Por qué?', min: 20, rows: 2 }],
        sol: { dada: 'El Teide, a Tenerife, amb més de 3.700 m.|El Teide, en Tenerife, con más de 3.700 m.', font: 'Una enciclopèdia en línia|Una enciclopedia en línea', existeix: 0, igual: 1,
          conclusio: "Sí: dues fonts fiables diuen el mateix volcà, i l'alçada només canvia uns metres d'una font a l'altra.|Sí: dos fuentes fiables dicen el mismo volcán, y la altura solo cambia unos metros de una fuente a otra." } },
      { k: 'quiz', ph: 'prova', q: "El xat t'ha donat una font amb un enllaç que funciona. Ja pots copiar la dada?|El chat te ha dado una fuente con un enlace que funciona. ¿Ya puedes copiar el dato?",
        opts: ["Encara no: he de mirar que la pàgina digui el mateix, i millor en dues fonts|Todavía no: tengo que mirar que la página diga lo mismo, y mejor en dos fuentes", "Sí: si l'enllaç funciona, la dada és certa|Sí: si el enlace funciona, el dato es cierto", 'Sí, si la resposta és llarga i segura|Sí, si la respuesta es larga y segura'], a: 0,
        ex: "Una font real pot dir una altra cosa, o el xat la pot haver resumit malament. Llegeix-la tu.|Una fuente real puede decir otra cosa, o el chat la puede haber resumido mal. Léela tú." },
      { k: 'iaext', ph: 'crea', tool: 'xat', q: "<b>Missió 4.</b> Converteix el xat en un tutor de mates que no et dona la solució.|<b>Misión 4.</b> Convierte el chat en un tutor de mates que no te da la solución.",
        goal: 'Resoldre un problema de mates tu, amb les preguntes i les pistes del xat, i comprovar-ho.|Resolver un problema de mates tú, con las preguntas y las pistas del chat, y comprobarlo.',
        steps: [{ t: 'Conversa nova. Enganxa aquest prompt de tutor:|Conversación nueva. Pega este prompt de tutor:', copy: "Fes de tutor de mates per a 2n d'ESO. No em donis la solució: fes-me una pregunta o una pista cada vegada i espera la meva resposta. El problema: «La Laia té el triple de cromos que en Pau. Entre tots dos en tenen 48. Quants cromos té cadascú?»|Haz de tutor de mates para 2.º de ESO. No me des la solución: hazme una pregunta o una pista cada vez y espera mi respuesta. El problema: «Laia tiene el triple de cromos que Pau. Entre los dos tienen 48. ¿Cuántos cromos tiene cada uno?»" },
          { t: "Respon amb les teves paraules, sense mirar enlloc. Si t'encalles, demana una pista.|Responde con tus palabras, sin mirar en ningún sitio. Si te atascas, pide una pista." },
          { t: "A mig problema, prova una vegada d'escriure-li «Dona'm la solució». Què fa?|A mitad del problema, prueba una vez a escribirle «Dame la solución». ¿Qué hace?" },
          { t: "Quan tinguis la resposta, comprova-la tu: sumen 48? L'una és el triple de l'altra?|Cuando tengas la respuesta, compruébala tú: ¿suman 48? ¿Una es el triple de la otra?" }],
        tip: "Si et dona la solució de cop, recorda-li: «Recorda que no em pots donar la solució, només pistes».|Si te da la solución de golpe, recuérdale: «Recuerda que no me puedes dar la solución, solo pistas».",
        expect: "Amb aquest prompt, el xat sol fer preguntes («Si en Pau en té x, quants en té la Laia?») i pistes, i espera la resposta. Quan li demanes la solució, uns cops et dona una altra pista i uns altres te la dona: per això cal recordar-li la instrucció. Solució: en Pau en té 12 i la Laia 36 (12 + 36 = 48 i 36 = 3 × 12).|Con este prompt, el chat suele hacer preguntas («Si Pau tiene x, ¿cuántos tiene Laia?») y pistas, y espera la respuesta. Cuando le pides la solución, unas veces te da otra pista y otras te la da: por eso hay que recordarle la instrucción. Solución: Pau tiene 12 y Laia 36 (12 + 36 = 48 y 36 = 3 × 12).",
        title: 'Diari del laboratori: el xat com a tutor|Diario del laboratorio: el chat como tutor',
        fields: [{ k: 'missatges', label: 'Quants missatges li has escrit?|¿Cuántos mensajes le has escrito?', num: true, lo: 1, hi: 40, unit: 'missatges|mensajes' },
          { k: 'feia', label: 'Què ha fet el xat? (tria tot el que hagi passat)|¿Qué ha hecho el chat? (elige todo lo que haya pasado)', choices: ["M'ha fet preguntes|Me ha hecho preguntas", "M'ha donat pistes|Me ha dado pistas", "M'ha corregit un error|Me ha corregido un error", "M'ha donat la solució massa aviat|Me ha dado la solución demasiado pronto"], multi: true, min: 1 },
          { k: 'demana', label: 'Quan li has demanat la solució…|Cuando le has pedido la solución…', choices: ["Me l'ha donada|Me la ha dado", "M'ha donat una altra pista|Me ha dado otra pista", "M'ha preguntat què havia provat|Me ha preguntado qué había probado"] },
          { k: 'solucio', label: "La teva solució i com l'has comprovada|Tu solución y cómo la has comprobado", hint: 'Pau: … Laia: … Comprovació: …|Pau: … Laia: … Comprobación: …', min: 15, rows: 2 }],
        sol: { missatges: '5', feia: [0, 1], demana: 1, solucio: "En Pau en té 12 i la Laia 36. Comprovació: 12 + 36 = 48 i 36 és el triple de 12.|Pau tiene 12 y Laia 36. Comprobación: 12 + 36 = 48 y 36 es el triple de 12." },
        pro: { q: "<b>Missió 4 (PRO).</b> Un tutor per a un problema de 3r d'ESO que no et doni la solució.|<b>Misión 4 (PRO).</b> Un tutor para un problema de 3.º de ESO que no te dé la solución.",
          steps: [{ t: 'Conversa nova. Enganxa aquest prompt de tutor:|Conversación nueva. Pega este prompt de tutor:', copy: "Fes de tutor de mates per a 3r d'ESO. No em donis la solució: fes-me una pregunta o una pista cada vegada i espera la meva resposta. El problema: «Un rectangle fa 30 cm de perímetre i la base fa 3 cm més que l'altura. Quant fan la base i l'altura?»|Haz de tutor de mates para 3.º de ESO. No me des la solución: hazme una pregunta o una pista cada vez y espera mi respuesta. El problema: «Un rectángulo tiene 30 cm de perímetro y la base mide 3 cm más que la altura. ¿Cuánto miden la base y la altura?»" },
            { t: "Respon amb les teves paraules, sense mirar enlloc. Si t'encalles, demana una pista.|Responde con tus palabras, sin mirar en ningún sitio. Si te atascas, pide una pista." },
            { t: "A mig problema, prova una vegada d'escriure-li «Dona'm la solució». Què fa?|A mitad del problema, prueba una vez a escribirle «Dame la solución». ¿Qué hace?" },
            { t: "Quan tinguis la resposta, comprova-la tu: el perímetre fa 30 cm? La base fa 3 cm més que l'altura?|Cuando tengas la respuesta, compruébala tú: ¿el perímetro mide 30 cm? ¿La base mide 3 cm más que la altura?" }],
          expect: "El xat sol començar per una pregunta («Si l'altura fa x, quant fa la base?») i guiar fins a l'equació 2 · (x + x + 3) = 30. Quan li demanes la solució, uns cops et dona una pista i uns altres te la dona: recorda-li la instrucció. Solució: altura 6 cm i base 9 cm (2 · (9 + 6) = 30).|El chat suele empezar por una pregunta («Si la altura mide x, ¿cuánto mide la base?») y guiar hasta la ecuación 2 · (x + x + 3) = 30. Cuando le pides la solución, unas veces te da una pista y otras te la da: recuérdale la instrucción. Solución: altura 6 cm y base 9 cm (2 · (9 + 6) = 30).",
          fields: [{ k: 'missatges', label: 'Quants missatges li has escrit?|¿Cuántos mensajes le has escrito?', num: true, lo: 1, hi: 40, unit: 'missatges|mensajes' },
            { k: 'feia', label: 'Què ha fet el xat? (tria tot el que hagi passat)|¿Qué ha hecho el chat? (elige todo lo que haya pasado)', choices: ["M'ha fet preguntes|Me ha hecho preguntas", "M'ha donat pistes|Me ha dado pistas", "M'ha corregit un error|Me ha corregido un error", "M'ha donat la solució massa aviat|Me ha dado la solución demasiado pronto"], multi: true, min: 1 },
            { k: 'demana', label: 'Quan li has demanat la solució…|Cuando le has pedido la solución…', choices: ["Me l'ha donada|Me la ha dado", "M'ha donat una altra pista|Me ha dado otra pista", "M'ha preguntat què havia provat|Me ha preguntado qué había probado"] },
            { k: 'solucio', label: "La teva solució i com l'has comprovada|Tu solución y cómo la has comprobado", hint: 'Altura: … Base: … Comprovació: …|Altura: … Base: … Comprobación: …', min: 15, rows: 2 }],
          sol: { missatges: '6', feia: [0, 1, 2], demana: 2, solucio: "Altura 6 cm i base 9 cm. Comprovació: 2 · (9 + 6) = 30 i 9 = 6 + 3.|Altura 6 cm y base 9 cm. Comprobación: 2 · (9 + 6) = 30 y 9 = 6 + 3." } } },
      { k: 'quiz', ph: 'repte', q: "El xat-tutor s'equivoca en un càlcul: diu que 48 ÷ 4 = 14. Què fas?|El chat-tutor se equivoca en un cálculo: dice que 48 ÷ 4 = 14. ¿Qué haces?",
        opts: ["L'hi dic, ho comprovo jo i segueixo amb el càlcul correcte|Se lo digo, lo compruebo yo y sigo con el cálculo correcto", "M'ho crec: és una IA|Me lo creo: es una IA", 'Tanco el xat i no el faig servir mai més|Cierro el chat y no lo uso nunca más'], a: 0,
        ex: "48 ÷ 4 = 12. Un bon tutor també s'equivoca de tant en tant: comprovar els càlculs és part d'aprendre.|48 ÷ 4 = 12. Un buen tutor también se equivoca de vez en cuando: comprobar los cálculos es parte de aprender." },
      { k: 'iaext', ph: 'repte', tool: 'xat', extra: true, q: "<b>Missió extra.</b> Demana al xat que revisi un prompt pobre. Coincideix amb la rúbrica?|<b>Misión extra.</b> Pide al chat que revise un prompt pobre. ¿Coincide con la rúbrica?",
        goal: 'Comparar els consells del xat amb les sis peces d\'un bon prompt.|Comparar los consejos del chat con las seis piezas de un buen prompt.',
        steps: [{ t: 'Conversa nova. Enganxa aquesta petició:|Conversación nueva. Pega esta petición:', copy: "Aquest prompt és massa pobre: «fotosíntesi». Quines coses li falten perquè la resposta serveixi per estudiar a 1r d'ESO? Respon en una llista curta, sense escriure el prompt nou.|Este prompt es demasiado pobre: «fotosíntesis». ¿Qué cosas le faltan para que la respuesta sirva para estudiar en 1.º de ESO? Responde en una lista corta, sin escribir el prompt nuevo." },
          { t: 'Marca quines peces de la rúbrica ha dit i escriu tu el prompt millorat.|Marca qué piezas de la rúbrica ha dicho y escribe tú el prompt mejorado.' }],
        expect: "Sol dir que hi falta per a qui és (el nivell), què vols exactament (explicar, resumir…) i el format (llargada, punts). Menys sovint parla dels límits o de demanar-li que digui si dubta: aquestes peces les has d'afegir tu.|Suele decir que falta para quién es (el nivel), qué quieres exactamente (explicar, resumir…) y el formato (longitud, puntos). Menos a menudo habla de los límites o de pedirle que diga si duda: esas piezas las tienes que añadir tú.",
        title: 'Diari del laboratori: el xat revisa un prompt|Diario del laboratorio: el chat revisa un prompt',
        fields: [{ k: 'peces', label: 'Quines peces ha dit que faltaven?|¿Qué piezas ha dicho que faltaban?', choices: ['Context|Contexto', 'Tasca|Tarea', 'Format|Formato', 'Exemple|Ejemplo', 'Límits|Límites', 'Comprovar|Comprobar'], multi: true, min: 1 },
          { k: 'nou', label: 'El teu prompt millorat|Tu prompt mejorado', hint: "Estic a 1r d'ESO…|Estoy en 1.º de ESO…", min: 40, rows: 3 }],
        sol: { peces: [0, 1, 2], nou: "Estic a 1r d'ESO. Explica'm la fotosíntesi en 3 punts curts, amb un exemple d'una planta de casa. Sense paraules difícils. Si dubtes d'alguna cosa, digues-ho.|Estoy en 1.º de ESO. Explícame la fotosíntesis en 3 puntos cortos, con un ejemplo de una planta de casa. Sin palabras difíciles. Si dudas de algo, dilo." } },
      { k: 'iacard', ph: 'crea', kind: 'spec', ico: '💬', col: '#3D7BF4', kindT: 'Guia del xat|Guía del chat', title: "La meva guia per fer servir un xat d'IA|Mi guía para usar un chat de IA", name: "La meva guia del xat d'IA|Mi guía del chat de IA",
        q: "Fes la teva <b>guia</b> amb el que has après avui. Et servirà cada vegada que facis servir un xat d'IA.|Haz tu <b>guía</b> con lo que has aprendido hoy. Te servirá cada vez que uses un chat de IA.",
        fields: [{ k: 'prompt', label: "El meu millor prompt d'avui|Mi mejor prompt de hoy", hint: 'El prompt bo de la missió 1, millorat|El prompt bueno de la misión 1, mejorado', min: 40, rows: 3 },
          { k: 'alluc', label: "Com sabré si s'inventa alguna cosa|Cómo sabré si se inventa algo", min: 20, rows: 2 },
          { k: 'fonts', label: 'Què faré amb les fonts que em doni|Qué haré con las fuentes que me dé', min: 20, rows: 2 },
          { k: 'tutor', label: 'Com el faré servir per estudiar|Cómo lo usaré para estudiar', min: 20, rows: 2 },
          { k: 'mai', label: 'Què no hi escriuré mai|Qué no escribiré nunca', choices: ["Dades personals, meves o d'altres|Datos personales, míos o de otros", 'Contrasenyes|Contraseñas', 'Fotos de persones|Fotos de personas', 'Preguntes sobre persones reals del meu entorn|Preguntas sobre personas reales de mi entorno'], multi: true, min: 2 }],
        sol: { prompt: "Estic a 2n d'ESO i tinc un examen de ciències. Explica'm com es forma un volcà en 4 punts curts, amb un exemple. Màxim 80 paraules. Si no estàs segur d'alguna cosa, digues-ho.|Estoy en 2.º de ESO y tengo un examen de ciencias. Explícame cómo se forma un volcán en 4 puntos cortos, con un ejemplo. Máximo 80 palabras. Si no estás seguro de algo, dilo.",
          alluc: "Si em dona dades molt exactes, noms o dates de coses poc conegudes, les busco en dues fonts. Si no les trobo, no les faig servir.|Si me da datos muy exactos, nombres o fechas de cosas poco conocidas, los busco en dos fuentes. Si no los encuentro, no los uso.",
          fonts: "Obrir l'enllaç, mirar que digui el mateix i buscar la dada en una altra font fiable.|Abrir el enlace, mirar que diga lo mismo y buscar el dato en otra fuente fiable.",
          tutor: "Li demano que faci de tutor: preguntes i pistes, sense la solució, i comprovo els càlculs.|Le pido que haga de tutor: preguntas y pistas, sin la solución, y compruebo los cálculos.", mai: [0, 1, 2, 3] } },
      { k: 'quiz', ph: 'tanca', q: "Quina d'aquestes frases resumeix millor el taller d'avui?|¿Cuál de estas frases resume mejor el taller de hoy?",
        opts: ["Un xat de veritat respon millor amb un bon prompt, però s'ha de comprovar i és més útil com a tutor|Un chat de verdad responde mejor con un buen prompt, pero hay que comprobarlo y es más útil como tutor", 'Un xat de veritat no s\'equivoca mai, a diferència dels simulats|Un chat de verdad no se equivoca nunca, a diferencia de los simulados', 'Com més curt és el prompt, millor és la resposta|Cuanto más corto es el prompt, mejor es la respuesta'], a: 0,
        ex: "Les mateixes idees que al simulador, ara amb una IA de veritat. A la unitat 4 faràs el mateix amb imatges.|Las mismas ideas que en el simulador, ahora con una IA de verdad. En la unidad 4 harás lo mismo con imágenes." },
      { k: 'feel', ph: 'tanca' }
    ] }
] };
